const conceptMessages=defineMessages({ru:{eyebrow:"\u041A\u043E\u043D\u0446\u0435\u043F\u0446\u0438\u044F \xB7 \u0432\u0435\u0440\u0441\u0438\u044F 41",title:"\u0421\u0432\u043E\u0451 \u043C\u0435\u0441\u0442\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u0432\u0430\u0448\u0438\u0445 \u0430\u0432\u0442\u043E\u0440\u043E\u0432.",lead:"\u0422\u0451\u043F\u043B\u0430\u044F \u043A\u043E\u043C\u043D\u0430\u0442\u0430, \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u0448\u043A\u0430\u0444 \u0438 \u043F\u043B\u043E\u0442\u043D\u0430\u044F \u043F\u043E\u043B\u043A\u0430, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0445\u043E\u0447\u0435\u0442\u0441\u044F \u0438\u0441\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u044C. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u2014 \u044F\u0437\u044B\u043A\u0438, \u0444\u043E\u0440\u043C\u0430 \u0438 \u0431\u043B\u0438\u0437\u043A\u0438\u0435 \u0430\u0432\u0442\u043E\u0440\u044B. \u0417\u0430\u0442\u0435\u043C \u0436\u0438\u0432\u0430\u044F \u043A\u0430\u0440\u0442\u0438\u043D\u0430 \u0437\u043D\u0430\u043A\u043E\u043C\u0438\u0442 \u0441 Series, \u043F\u043E\u0447\u0442\u0430 \u2014 \u0441\u043E \u0441\u0442\u0440\u043E\u043A\u0430\u043C\u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u0435\u0439, \u0430 \u043C\u0435\u0441\u044F\u0447\u043D\u0430\u044F \u0430\u0444\u0438\u0448\u0430 \u2014 \u0441 \u0431\u0443\u0434\u0443\u0449\u0435\u0439 \u043B\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043D\u043E\u0439 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u043E\u0439. \u041A \u0447\u0442\u0435\u043D\u0438\u044E \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u043B\u044E\u0431\u043E\u0439 \u043C\u043E\u043C\u0435\u043D\u0442.",sections:[{label:"01 / \u041D\u0430 \u0447\u0451\u043C \u0441\u0442\u043E\u0438\u0442 \u0440\u0435\u0448\u0435\u043D\u0438\u0435",title:"\u0412\u0441\u0442\u0440\u0435\u0447\u0430 \u0437\u0430\u0434\u0430\u0451\u0442 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u043A \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044E.",html:'<p>\u041E\u0431\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u044F 14 \u0438 15 \u043D\u043E\u044F\u0431\u0440\u044F \u0437\u0430\u0434\u0430\u044E\u0442 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u043A \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044E: \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u0435\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0438 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442, \u0433\u043E\u0441\u0442\u0435\u043F\u0440\u0438\u0438\u043C\u043D\u043E \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0442\u044C \u0438 \u043F\u043E\u043C\u043E\u0433\u0430\u0442\u044C \u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0441\u0432\u043E\u0451 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u043E. \u041A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0435 \u044D\u043A\u0440\u0430\u043D\u044B \u043D\u0438\u0436\u0435 \u2014 \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u044D\u0442\u043E\u0439 \u0440\u0430\u0431\u043E\u0442\u044B, \u0430 \u043D\u0435 \u0434\u043E\u0441\u043B\u043E\u0432\u043D\u043E \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D\u043D\u044B\u0439 \u043C\u0430\u0440\u0448\u0440\u0443\u0442 \u0432\u0441\u0442\u0440\u0435\u0447\u0438.</p><div class="scenario-table"><table><thead><tr><th>\u0418\u0441\u0442\u043E\u0447\u043D\u0438\u043A</th><th>\u0421\u043E\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0435</th><th>\u0421\u043B\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u0434\u043B\u044F \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F\u0430</th></tr></thead><tbody><tr><td>14 \u043D\u043E\u044F\u0431\u0440\u044F, \u0441\u0442\u0440\u043E\u043A\u0438 626\u2013636, 764\u2013802, 874\u2013875</td><td>\u0423\u0437\u043D\u0430\u0432\u0430\u043D\u0438\u0435 \u043F\u0440\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0438, \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u043B\u0430\u0439\u043A\u043E\u0432, \u043F\u0443\u0442\u044C \u043F\u043E\u0441\u043B\u0435 \u0432\u0445\u043E\u0434\u0430 \u0438 \u0433\u043E\u0441\u0442\u0435\u043F\u0440\u0438\u0438\u043C\u0441\u0442\u0432\u043E.</td><td>\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0438 \u043C\u0435\u0441\u0442\u043E; \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u044F\u0442\u044C \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435\u043C.</td></tr><tr><td>15 \u043D\u043E\u044F\u0431\u0440\u044F, \u0447\u0430\u0441\u0442\u044C 3, 12:04\u201316:01; \u0441\u0442\u0440\u043E\u043A\u0438 1413\u20131461</td><td>\u041D\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u0442\u044C \u043E\u0431\u0449\u0438\u0439 \u0432\u0445\u043E\u0434 \u0441\u043E \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430; \u0434\u0430\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u044B\u0435 \u0438\u043C\u0435\u043D\u0430, \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u043E \u0443\u0433\u043B\u0443\u0431\u043B\u044F\u0442\u044C \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0443\u044E \u0431\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u044E \u0438 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u0430.</td><td>\u041A\u043E\u043C\u043D\u0430\u0442\u0430 \u2192 \u0448\u043A\u0430\u0444 \u0441 \u0430\u0432\u0442\u043E\u0440\u0430\u043C\u0438 \u2192 \u043F\u0435\u0440\u0432\u044B\u0439 \u0442\u0435\u043A\u0441\u0442. \u0413\u043B\u0443\u0431\u043E\u043A\u043E\u0435 \u0432\u043E\u0441\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u0435 \u2014 \u043F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E.</td></tr><tr><td>15 \u043D\u043E\u044F\u0431\u0440\u044F, \u0447\u0430\u0441\u0442\u044C 3, 16:01\u201319:09</td><td>\u0420\u0430\u0437\u0434\u0435\u043B\u0438\u0442\u044C \u0432\u0440\u0435\u043C\u044F \u0432\u043D\u0443\u0442\u0440\u0438 \u0441\u0435\u0440\u0432\u0438\u0441\u0430 \u0438 \u043F\u0440\u0438\u0447\u0438\u043D\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F; \u043E\u0431\u0441\u0443\u0436\u0434\u0430\u043B\u0438\u0441\u044C \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0438\u0433\u0440\u044B \u0438 \u0431\u0443\u0434\u0443\u0449\u0438\u0435 \u043D\u0430\u0433\u0440\u0430\u0434\u044B.</td><td>\u041B\u0451\u0433\u043A\u0430\u044F \u0438\u0433\u0440\u043E\u0432\u0430\u044F \u043E\u0431\u0440\u0430\u0442\u043D\u0430\u044F \u0441\u0432\u044F\u0437\u044C \u0437\u0430 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440, \u0431\u0435\u0437 \u0432\u0430\u043B\u044E\u0442\u044B \u0438 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0438\u0433\u0440.</td></tr><tr><td>15 \u043D\u043E\u044F\u0431\u0440\u044F, \u0447\u0430\u0441\u0442\u044C 3, 21:15\u201322:19</td><td>\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441: \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435, \u043F\u0440\u043E\u0437\u0430 \u0438\u043B\u0438 \u043F\u043E\u044D\u0437\u0438\u044F, \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0438 \u0438\u043B\u0438 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435.</td><td>\u041D\u0435 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0442\u044C \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u043D\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0432 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u044B\u0439 \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C.</td></tr></tbody></table></div><p>\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440 \u043D\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0431\u044B\u043B \u043D\u0430\u0437\u0432\u0430\u043D \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C; \u0447\u0438\u0441\u043B\u0430 \u043F\u044F\u0442\u044C \u0438\u0437 \u0434\u0432\u0430\u0434\u0446\u0430\u0442\u0438 \u0438 \u043E\u0431\u0440\u0430\u0437 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u0430 \u0431\u044B\u043B\u0438 \u043F\u0440\u0438\u043C\u0435\u0440\u0430\u043C\u0438. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043F\u0440\u043E\u0441\u044C\u0431\u0430 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u043F\u0440\u044F\u043C\u043E \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043D\u0435 \u043F\u0440\u0438\u043D\u0443\u0436\u0434\u0430\u0442\u044C \u043A \u043D\u0435\u0436\u0435\u043B\u0430\u043D\u043D\u044B\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F\u043C. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442 \u043A\u0432\u043E\u0442\u044B: \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0445 \u0430\u0432\u0442\u043E\u0440\u043E\u0432, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043D\u043E\u043B\u044C, \u0438 \u0441\u0440\u0430\u0437\u0443 \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0447\u0442\u0435\u043D\u0438\u044E. \u041C\u0435\u0441\u0442\u043E \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0438 \u0438\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F \u0434\u043B\u044F \u043F\u0440\u044F\u043C\u044B\u0445 \u0441\u0441\u044B\u043B\u043E\u043A \u0432 \u0441\u043E\u0437\u0432\u043E\u043D\u0435 \u043D\u0435 \u0431\u044B\u043B\u0438 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0440\u0435\u0448\u0435\u043D\u044B. \u0421\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0437\u0434\u0435\u0441\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u044B \u2014 \u043D\u0430\u0448\u0435 \u043F\u0440\u043E\u0435\u043A\u0442\u043D\u043E\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0435.</p>'},{label:"\u041E\u0442\u043A\u0440\u044B\u0442\u0438\u044F / \u0432\u0435\u0440\u0441\u0438\u044F 41",title:"\u0423\u0437\u043D\u0430\u0442\u044C Boks \u0447\u0435\u0440\u0435\u0437 \u043C\u0430\u043B\u0435\u043D\u044C\u043A\u0438\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F.",html:"<p>\u041E\u0431\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0435 16 \u043D\u043E\u044F\u0431\u0440\u044F \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0430\u043B\u043E \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u0447\u043D\u043E\u0435 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u043E \u0438 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F. \u041F\u043E\u043B\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0440\u0430\u0437\u043D\u044B\u0435 \u043A\u043D\u0438\u0433\u0438: \u043A\u043E\u0440\u0435\u0448\u043A\u0438, \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0438 \u0441\u0442\u043E\u043F\u043A\u0438. \u0413\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043D\u0438\u0433\u0438 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0446\u0435\u043B\u044C\u043D\u044B\u0439 \u0442\u043A\u0430\u043D\u0435\u0432\u044B\u0439 \u043F\u0435\u0440\u0435\u043F\u043B\u0451\u0442 \u0441\u043F\u0435\u0440\u0435\u0434\u0438, \u0431\u0435\u0437 \u0438\u0441\u043A\u0443\u0441\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0433\u043E \u0432\u0438\u0434\u0430 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0441\u0432\u0435\u0440\u0445\u0443. \u041F\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u044E \u043A\u043D\u0438\u0433\u0430 \u043F\u043E\u0434\u043B\u0435\u0442\u0430\u0435\u0442 \u043E\u0442 \u0441\u0432\u043E\u0435\u0433\u043E \u043C\u0435\u0441\u0442\u0430 \u043A \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044E; \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0431\u0435\u043B\u0430\u044F \u043A\u043D\u043E\u043F\u043A\u0430 \u0432\u044B\u0431\u043E\u0440\u0430 \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043F\u043E\u0434 \u043D\u0435\u0439. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043D\u0430 \u043E\u0442\u043A\u0440\u044B\u0442\u0443\u044E \u043E\u0431\u043B\u043E\u0436\u043A\u0443, \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435, \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u0441\u043D\u0430\u0440\u0443\u0436\u0438 \u0438\u043B\u0438 Escape \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043A\u043D\u0438\u0433\u0443 \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438. \u0424\u043E\u043A\u0443\u0441 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432\u043D\u0443\u0442\u0440\u0438 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0430, \u0437\u0430\u0442\u0435\u043C \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043A \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0439 \u043A\u043D\u0438\u0433\u0435. Resize \u0438 \u0441\u043C\u0435\u043D\u0430 \u044D\u0442\u0430\u043F\u0430 \u0443\u0431\u0438\u0440\u0430\u044E\u0442 \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440. \u041A\u0432\u043E\u0442\u044B \u0438 \u0432\u044B\u0434\u0443\u043C\u0430\u043D\u043D\u044B\u0445 \u043F\u043E\u0434\u043F\u0438\u0441\u043E\u043A \u043D\u0435\u0442.</p><p>\u0412 \u0436\u0438\u0432\u043E\u0439 \u043A\u0430\u0440\u0442\u0438\u043D\u0435 \u2014 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 Series \u0441 \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u043C\u0438 \u0437\u0430\u043F\u0438\u0441\u044F\u043C\u0438, \u0438\u043B\u043B\u044E\u0441\u0442\u0440\u0430\u0446\u0438\u044F\u043C\u0438 \u0438 \u0440\u0430\u0437\u043C\u0435\u0442\u043A\u043E\u0439 \u0441\u043B\u043E\u0432. \u041D\u0430 \u0440\u0443\u0441\u0441\u043A\u043E\u043C \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \xAB\u043F\u043E\u043B\u0435\u0442 \u0441\u043A\u0432\u043E\u0437\u044C \u0441\u043D\u044B\xBB \u0410\u043B\u0435\u043A\u0441\u0435\u044F \u041F\u0440\u043E\u0445\u043E\u0440\u043E\u0432\u0430; \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0438 \xAB\u0417\u0432\u0451\u0437\u0434\u043D\u043E\u0435\xBB \u0414\u0430\u0440\u044C\u0438 \u041C\u0430\u043B\u044C\u043E-\u0421\u0443\u0431\u0431\u043E\u0442\u0438\u043D\u043E\u0439. \u041D\u0430 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u043F\u0435\u0440\u0432\u044B\u043C \u0438\u0434\u0451\u0442 \xABThere is no Frigate like a Book\xBB \u042D\u043C\u0438\u043B\u0438 \u0414\u0438\u043A\u0438\u043D\u0441\u043E\u043D; \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \xABA Dream Within a Dream\xBB \u042D\u0434\u0433\u0430\u0440\u0430 \u041F\u043E. \u042D\u0442\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0435\u0432\u044C\u044E \u043A\u043E\u043C\u043D\u0430\u0442\u044B, \u0430 \u043D\u0435 \u043F\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0433\u043E \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430. \u041A\u0430\u0440\u0442\u0438\u043D\u0430 \u0438 \u0441\u043B\u043E\u0432\u0430 \u043E\u0436\u0438\u0432\u0430\u044E\u0442 \u0441\u0430\u043C\u0438 \u0431\u0435\u0437 \u0437\u0432\u0443\u043A\u0430, \u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u0441\u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438. \u0421\u0442\u0440\u0435\u043B\u043E\u043A \u0438 \u0440\u0443\u0447\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F \u043D\u0435\u0442; \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0438\u043B\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0433\u043E\u043B\u043E\u0441. \u0411\u0430\u0440\u0445\u0430\u0442\u043D\u044B\u0435 \u0448\u0442\u043E\u0440\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442\u0441\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u043C\u0438 \u0438 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0443\u0445\u043E\u0434\u044F\u0442 \u0437\u0430 \u0440\u0430\u043C\u0443. \u041A \u0447\u0442\u0435\u043D\u0438\u044E \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u043B\u044E\u0431\u043E\u0439 \u043C\u043E\u043C\u0435\u043D\u0442.</p><p>\u0412 \u0432\u0435\u0440\u0441\u0438\u0438 35 \u0442\u0438\u043F\u043E\u0433\u0440\u0430\u0444\u0438\u043A\u0430 Series \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u0448\u0438\u0440\u0438\u043D\u0443 390, \u0430 \u0432\u044B\u0441\u043E\u0442\u0443 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0442 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u0433\u043E \u043F\u0440\u043E\u0451\u043C\u0430 \u043A\u0430\u0440\u0442\u0438\u043D\u044B. \u041F\u0440\u0435\u0436\u043D\u044F\u044F \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0441\u0446\u0435\u043D\u0430 390\xD7693\u2153 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0443\u043C\u0435\u043D\u044C\u0448\u0430\u0435\u0442\u0441\u044F \u0446\u0435\u043B\u0438\u043A\u043E\u043C \u0434\u043E \u043A\u0440\u043E\u0448\u0435\u0447\u043D\u044B\u0445 \u0431\u0443\u043A\u0432. \u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u044B \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0435 Playfair, \u043D\u0430\u0447\u0435\u0440\u0442\u0430\u043D\u0438\u044F, textScale, \u0444\u0440\u0430\u0437\u044B, \u043C\u043E\u043C\u0435\u043D\u0442\u044B \u043F\u043E\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0441\u043B\u043E\u0432 \u0438 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F. \u041A\u0430\u0436\u0434\u0430\u044F \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u0430\u044F \u0437\u043E\u043D\u0430 \u0432\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0441 \u0443\u0447\u0451\u0442\u043E\u043C \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u0445 \u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u044B\u0445 \u0442\u0438\u0442\u0440\u043E\u0432. \u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0438 \u0430\u0432\u0442\u043E\u0440 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441\u0432\u0435\u0440\u0445\u0443; \u0432\u0441\u0435 \u0441\u043B\u043E\u0432\u0430 \u0434\u043E\u043B\u0436\u043D\u044B \u043F\u043E\u043C\u0435\u0449\u0430\u0442\u044C\u0441\u044F \u0432\u043D\u0443\u0442\u0440\u0438. \u041D\u0438\u0436\u043D\u0435\u0439 \u043B\u0438\u043D\u0438\u0438 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u0430 \u043D\u0435\u0442. \u041D\u0435\u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u0430\u044F \u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u044F\u044F \u043A\u0440\u043E\u043C\u043A\u0430 \u0440\u0430\u043C\u044B \u0442\u043E\u043B\u0449\u0438\u043D\u043E\u0439 2 px \u0441\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0448\u0432\u044B \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0446\u0438\u0438.</p><p>\u041E\u0442 \u043A\u0430\u0440\u0442\u0438\u043D\u044B \u043A\u0430\u043C\u0435\u0440\u0430 \u0434\u0432\u0438\u0436\u0435\u0442\u0441\u044F \u043F\u043E \u0435\u0434\u0438\u043D\u043E\u0439 \u043F\u0430\u043D\u043E\u0440\u0430\u043C\u0435 \u043A \u0441\u0442\u043E\u043B\u0443, \u0437\u0430\u0442\u0435\u043C \u043F\u0440\u0438\u0431\u043B\u0438\u0436\u0430\u0435\u0442\u0441\u044F \u043A \u0435\u0433\u043E \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438. \u0421\u0442\u0435\u043D\u044B \u043D\u0435 \u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F; \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0430 \u043A\u0443\u0431\u0438\u043A\u043E\u043C \u043D\u0435\u0442. \u041E\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043C\u0430\u0441\u0448\u0442\u0430\u0431 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043F\u043B\u0430\u0432\u043D\u043E \u043F\u043E \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D\u043D\u044B\u043C \u043F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043E\u0447\u043D\u044B\u043C \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F\u043C; \u043F\u0440\u0435\u0436\u043D\u0435\u0433\u043E \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u0430 \u0443\u043C\u0435\u043D\u044C\u0448\u0435\u043D\u0438\u044F \u0432 \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0435 \u043D\u0435\u0442. \u041D\u0430 \u0432\u044B\u0441\u043E\u043A\u043E\u043C \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0435 \u043F\u0430\u043D\u043E\u0440\u0430\u043C\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u043A\u0440\u044B\u0442\u0438\u0435 \u043A\u0430\u0434\u0440\u0430, \u043D\u0435 \u0441\u0434\u0432\u0438\u0433\u0430\u044F \u0432\u0435\u0440\u0445 \u043A\u0430\u0440\u0442\u0438\u043D\u044B. \u0411\u0443\u043C\u0430\u0433\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u0431\u043B\u0438\u0436\u0435\u043D\u0438\u044F \u043A \u0441\u0442\u043E\u043B\u0443. \u041C\u0435\u0436\u0434\u0443 \u043F\u043E\u0447\u0442\u043E\u0439 \u0438 \xAB\u0410\u0444\u0438\u0448\u0435\u0439\xBB \u0432\u0437\u0433\u043B\u044F\u0434 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u0442\u043E\u043C\u0443 \u0436\u0435 \u0441\u0442\u043E\u043B\u0443: \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u043F\u0440\u0435\u0434\u043C\u0435\u0442 \u0443\u0445\u043E\u0434\u0438\u0442 \u043F\u0435\u0440\u0435\u0434 \u043F\u043E\u044F\u0432\u043B\u0435\u043D\u0438\u0435\u043C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E.</p><p>\u0412 \u043F\u043E\u0447\u0442\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u043E\u0434\u0438\u043D \u043B\u0438\u0441\u0442. \u041D\u0430\u0436\u0430\u0442\u0438\u0435 \u043D\u0430 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0441\u0442\u0440\u043E\u043A\u0438 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0438. \u0421\u0430\u043C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u043B\u0438\u0441\u0442 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0435\u0440\u0445\u043D\u0438\u043C \u0438 \u043D\u0438\u0436\u043D\u0438\u043C \u0441\u0433\u0438\u0431\u0430\u043C\u0438, \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0432\u0435\u0440\u0442, \u043A\u043B\u0430\u043F\u0430\u043D \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0437\u0430\u043F\u0435\u0447\u0430\u0442\u0430\u043D\u043D\u043E\u0435 \u043F\u0438\u0441\u044C\u043C\u043E \u043B\u0435\u0442\u0438\u0442 \u0432 \u0432\u0438\u0434\u0438\u043C\u0443\u044E \u043F\u0440\u043E\u0440\u0435\u0437\u044C. \u041F\u0435\u0447\u0430\u0442\u044C \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0438. \u041F\u043E\u0434 \u043D\u0438\u043C \u043D\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B: \u043F\u043E\u0441\u043B\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0438 \u0432\u0438\u0434\u0435\u043D \u0441\u0442\u043E\u043B \u0438 \u0441\u043F\u043E\u043A\u043E\u0439\u043D\u044B\u0439 \u0441\u0442\u0430\u0442\u0443\u0441. \u041A\u043E\u043D\u0432\u0435\u0440\u0442 \u0441\u043F\u0440\u0430\u0432\u0430 \u2014 \u0442\u043E\u043B\u044C\u043A\u043E \u0443\u043A\u0440\u0430\u0448\u0435\u043D\u0438\u0435, \u0431\u0435\u0437 \u043F\u043E\u0434\u043F\u0438\u0441\u0438 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u041D\u0430\u0434\u043F\u0438\u0441\u044C \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u043F\u0438\u0441\u0430\u043D\u0430 \u0432 \u043B\u0430\u0442\u0443\u043D\u043D\u0443\u044E \u0442\u0430\u0431\u043B\u0438\u0447\u043A\u0443 \u044F\u0449\u0438\u043A\u0430. \u0423\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 ResizeObserver \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0440\u0430\u0437\u043C\u0435\u0440\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435; \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0430\u044F \u0441\u043C\u0435\u043D\u0430 \u0440\u0430\u0437\u043C\u0435\u0440\u0430, \u0443\u0445\u043E\u0434 \u0438\u043B\u0438 reduced motion \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u043B\u0438\u0431\u043E \u043E\u0442\u043C\u0435\u043D\u044F\u044E\u0442 \u043F\u0440\u0438\u043D\u0430\u0434\u043B\u0435\u0436\u0430\u0449\u0443\u044E \u0441\u0446\u0435\u043D\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C. \u0412\u043E\u0437\u0432\u0440\u0430\u0442 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u043D\u043E\u0432\u044B\u0439 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u0438\u043C\u0435\u0440. \u041E\u0431\u044A\u044F\u0441\u043D\u0435\u043D\u0438\u0435 \u0441\u0432\u044F\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u0442\u0440\u043E\u043A\u0438 \u0438\u0437 bok \u0441\u043E \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u043C \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u0435\u043C, \u0430 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0435 \u043F\u0438\u0441\u044C\u043C\u0430 \u2014 \u0441 \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u043C. \u041B\u043E\u043A\u0430\u043B\u044C\u043D\u0430\u044F \u0438\u043B\u043B\u044E\u0441\u0442\u0440\u0430\u0446\u0438\u044F \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442, \u043D\u0435 \u0441\u043E\u0437\u0434\u0430\u0451\u0442 \u0430\u0434\u0440\u0435\u0441\u0430\u0442\u0430 \u0438 \u043D\u0435 \u043E\u0431\u0435\u0449\u0430\u0435\u0442 \u043C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u043E\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430.</p><p>\u0414\u043B\u044F \u043C\u0435\u0441\u044F\u0447\u043D\u043E\u0439 \xAB\u0410\u0444\u0438\u0448\u0438\xBB \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D \u043F\u0435\u0440\u0432\u044B\u0439 \u0438\u0437 \u043F\u044F\u0442\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432, \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u0432 \u0432\u0435\u0440\u0441\u0438\u0438 40: \u0442\u0451\u043C\u043D\u043E-\u0437\u0435\u043B\u0451\u043D\u0430\u044F \u0438 \u043A\u0430\u0440\u043C\u0438\u043D\u043E\u0432\u0430\u044F \u043F\u0435\u0447\u0430\u0442\u044C, \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u0438, \u0442\u0435\u0430\u0442\u0440\u0430\u043B\u044C\u043D\u044B\u0435 \u0431\u0438\u043B\u0435\u0442\u044B \u0438 \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u043F\u043E\u0441\u0442\u0435\u0440 \u043F\u043E\u0432\u0435\u0440\u0445 \u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u043D\u043E\u0439 \u0441\u0435\u0442\u043A\u0438. \u0411\u043E\u043B\u0435\u0435 \u043A\u0440\u0443\u043F\u043D\u044B\u0439 \u043B\u0438\u0441\u0442 \u0441 \u043F\u0440\u043E\u0437\u0440\u0430\u0447\u043D\u044B\u043C \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435\u043C \u043B\u0435\u0436\u0438\u0442 \u043F\u0440\u044F\u043C\u043E \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u043A\u043E\u043C\u043D\u0430\u0442\u044B, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044F \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u0438 \u0438 \u043C\u044F\u0433\u043A\u0443\u044E \u0442\u0435\u043D\u044C. \u0415\u0433\u043E \u0440\u0430\u0437\u043C\u0435\u0440 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u043E\u0439 \u043E\u0431\u043B\u0430\u0441\u0442\u044C\u044E \u043C\u0435\u0436\u0434\u0443 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u043E\u043C \u0438 \u043D\u0438\u0436\u043D\u0435\u0439 \u043A\u043D\u043E\u043F\u043A\u043E\u0439. \u0412 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0438 \u043D\u0435\u0442 \u0442\u0435\u043A\u0441\u0442\u0430: \u043E\u0431\u0449\u0438\u0439 \u043D\u0430\u0442\u0438\u0432\u043D\u044B\u0439 SVG-\u0441\u043B\u043E\u0439 \u0432\u044B\u0432\u043E\u0434\u0438\u0442 \u0440\u0443\u0441\u0441\u043A\u0438\u0439 \u0438\u043B\u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439 \u0442\u0435\u043A\u0441\u0442 \u0438 \u0432 \u043E\u043D\u0431\u043E\u0440\u0434\u0438\u043D\u0433\u0435, \u0438 \u043D\u0430 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435 \u0441\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u044F \u043F\u044F\u0442\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432. \u0414\u0430\u0442\u044B \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u044B \u043A \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u043C \u0433\u0440\u0430\u043D\u0438\u0446\u0430\u043C 42 \u044F\u0447\u0435\u0435\u043A, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0440\u0430\u0437\u043D\u0443\u044E \u0432\u044B\u0441\u043E\u0442\u0443 \u0440\u044F\u0434\u043E\u0432; \u0441\u0442\u0440\u043E\u043A\u0438 \u0431\u0438\u043B\u0435\u0442\u043E\u0432 \u0438 \u043F\u043E\u0441\u0442\u0435\u0440\u0430 \u2014 \u043A \u043F\u043B\u043E\u0441\u043A\u043E\u0441\u0442\u044F\u043C \u0431\u0443\u043C\u0430\u0433\u0438. \u041C\u0430\u0441\u043A\u0438 \u0441\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0435\u0447\u0430\u0442\u044C \u043F\u043E\u0434 \u043B\u0435\u0436\u0430\u0449\u0438\u043C\u0438 \u0441\u0432\u0435\u0440\u0445\u0443 \u043F\u0440\u0435\u0434\u043C\u0435\u0442\u0430\u043C\u0438. \u041D\u0435\u0434\u0435\u043B\u044F \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043F\u043E\u043D\u0435\u0434\u0435\u043B\u044C\u043D\u0438\u043A\u0430; \u043C\u0435\u0441\u044F\u0446, \u0433\u043E\u0434, \u0434\u043D\u0438 \u043D\u0435\u0434\u0435\u043B\u0438 \u0438 \u0434\u0430\u0442\u044B \u043B\u043E\u043A\u0430\u043B\u0438\u0437\u0443\u044E\u0442\u0441\u044F \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430\u043C\u0438 \u0444\u043E\u0440\u043C\u0430\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0434\u0430\u0442. \u041D\u0430\u0436\u0438\u043C\u0430\u0435\u043C\u044B\u0445 \u0441\u043E\u0431\u044B\u0442\u0438\u0439 \u0438 \u0431\u0440\u043E\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u043D\u0435\u0442. \u042D\u0442\u043E \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u0441 \u0431\u0443\u0434\u0443\u0449\u0435\u0439 \u043B\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043D\u043E\u0439 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u043E\u0439, \u0430 \u043D\u0435 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u0435 \u0440\u0430\u0441\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043E \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0441\u0442\u0438 \u0430\u0432\u0442\u043E\u0440\u043E\u0432. \u041F\u043E\u0441\u0435\u0449\u0435\u043D\u0438\u044F, \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0438 \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0447\u0442\u0435\u043D\u0438\u044F \u043D\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041B\u0438\u0447\u043D\u0430\u044F \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0447\u0442\u0435\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u043C \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u044F.</p><p>\u041D\u0430\u0437\u0430\u0434 \u043C\u043E\u0436\u043D\u043E \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043B\u044E\u0431\u043E\u043C\u0443 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u043C\u0443 \u044D\u0442\u0430\u043F\u0443; \u043E\u0442\u0432\u0435\u0442\u044B \u0438 \u043C\u0435\u0441\u0442\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F. \u041F\u0435\u0440\u0435\u0445\u043E\u0434 \u043A\u0430\u043C\u0435\u0440\u044B \u0440\u0430\u0437\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u043A\u0430\u0434\u0440\u0430. \u0423\u0445\u043E\u0434 \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0437\u0432\u0443\u043A \u0438 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0430\u0435\u0442 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441. \u0420\u0443\u0441\u0441\u043A\u0438\u0439 \u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u044B \u043E\u0442\u0434\u0435\u043B\u0435\u043D\u044B \u043E\u0442 \u044F\u0437\u044B\u043A\u0430 \u043B\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043D\u044B\u0445 \u043F\u0440\u0438\u043C\u0435\u0440\u043E\u0432. \u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0438\u0441\u0445\u043E\u0434\u043D\u0438\u043A\u043E\u0432 \u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0440\u0430\u0437\u043C\u0435\u0440\u043E\u0432 \u043E\u043A\u043D\u0430 \u0434\u043E\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u044B\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u043E\u043C; \u0443\u0441\u043F\u0435\u0448\u043D\u0430\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u043C\u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u043D\u0435 \u0434\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0443 \u043D\u0430 \u0432\u0441\u0435\u0445 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u0445.</p>"},{label:"02 / \u041F\u0435\u0440\u0432\u0430\u044F \u0432\u0441\u0442\u0440\u0435\u0447\u0430",title:"\u0417\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u0432\u043D\u0443\u0442\u0440\u0438 \u0436\u0438\u0432\u043E\u0433\u043E \u0448\u043A\u0430\u0444\u0430.",html:'<p>\u041F\u0435\u0440\u0432\u044B\u0439 \u043A\u0430\u0434\u0440 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0430\u0440\u043E\u0447\u043D\u043E\u0435 \u043E\u043A\u043D\u043E, \u043E\u043B\u0438\u0432\u043A\u043E\u0432\u043E\u0435 \u043A\u0440\u0435\u0441\u043B\u043E, \u0441\u0442\u043E\u043B\u0438\u043A \u0438 \u0442\u0451\u043F\u043B\u044B\u0439 \u0441\u0432\u0435\u0442. \xAB\u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C \u0432 Boks\xBB \u0438 \xAB\u041D\u0430\u0439\u0434\u0451\u043C \u0440\u0430\u0441\u0441\u043A\u0430\u0437\u044B \u0438 \u0441\u0442\u0438\u0445\u0438, \u0431\u043B\u0438\u0437\u043A\u0438\u0435 \u0432\u0430\u043C.\xBB \u043E\u0431\u044A\u044F\u0441\u043D\u044F\u044E\u0442 \u0446\u0435\u043B\u044C \u0432\u0441\u0442\u0440\u0435\u0447\u0438. \u0412\u043D\u0438\u0437\u0443 \u0441\u0442\u0432\u043E\u0440\u043A\u0438 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043C\u044F\u0433\u043A\u0430\u044F \u043F\u043E\u0434\u043F\u0438\u0441\u044C \xAB\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0448\u043A\u0430\u0444\xBB. \u0412\u044B\u0441\u043E\u043A\u0438\u0439 \u0448\u0438\u0440\u043E\u043A\u0438\u0439 \u0448\u043A\u0430\u0444 \u0438\u0437 \u043E\u0440\u0435\u0445\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0437\u0430 \u043F\u0440\u0430\u0432\u044B\u0439 \u043A\u0440\u0430\u0439; \u0448\u0438\u0440\u043E\u043A\u0430\u044F \u043C\u0430\u0442\u043E\u0432\u0430\u044F \u0441\u0442\u0432\u043E\u0440\u043A\u0430 \u0434\u0432\u0438\u0436\u0435\u0442\u0441\u044F \u043F\u043E \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0449\u0435\u0439, \u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u0430\u044F \u043C\u0430\u0441\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0441\u0442\u043E\u043B \u043F\u0435\u0440\u0435\u0434 \u043D\u0435\u0439. \u041C\u0430\u0440\u0448\u0440\u0443\u0442: \u044F\u0437\u044B\u043A\u0438 \u2192 \u0444\u043E\u0440\u043C\u0430 \u2192 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0438 \u2192 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u0438\u043A\u0438 \u043F\u0440\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0443\u0441\u0441\u043A\u043E\u043C. \u041F\u0440\u0438 \u043E\u0434\u043D\u043E\u043C \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u043F\u0440\u0435\u0434\u043F\u043E\u0447\u0442\u0435\u043D\u0438\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0430\u0445, \u0437\u0430\u0442\u0435\u043C \u0441\u043B\u0435\u0434\u0443\u0435\u0442 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u0441 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044F\u043C\u0438 Boks; \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440 \u043F\u0440\u0435\u0434\u043F\u043E\u0447\u0442\u0435\u043D\u0438\u0439 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0442\u0440\u0438 \u0448\u0430\u0433\u0430 \u0432\u043C\u0435\u0441\u0442\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445. <button data-scenario="onboarding">\u041F\u0440\u043E\u0439\u0442\u0438 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u2192</button></p><p>\u0414\u0432\u0430 \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u044B\u0445 \u043B\u0430\u0442\u0443\u043D\u043D\u044B\u0445 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0442\u0435\u043B\u044F \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \xAB\u0420\u0443\u0441\u0441\u043A\u0438\u0439\xBB \u0438 \xABEnglish\xBB: \u043E\u0434\u0438\u043D \u0438\u043B\u0438 \u043E\u0431\u0430. \u041D\u043E\u0432\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0441 \u0440\u0443\u0441\u0441\u043A\u043E\u0433\u043E \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u044F\u0437\u044B\u043A\u0430 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430; \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0439 \u044F\u0432\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440 \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u044F\u0437\u044B\u043A \u043D\u0435\u043B\u044C\u0437\u044F \u0432\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u044C. \u0421\u0432\u0435\u0447\u0435\u043D\u0438\u0435, \u0433\u0430\u043B\u043E\u0447\u043A\u0430 \u0438 \u044F\u0440\u043A\u0430\u044F \u043F\u043E\u0434\u043F\u0438\u0441\u044C \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0432\u044B\u0431\u043E\u0440; \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u0430\u044F \u043F\u043E\u0434\u043F\u0438\u0441\u044C \u043F\u0440\u0438\u0433\u043B\u0443\u0448\u0430\u0435\u0442\u0441\u044F. \u042F\u0437\u044B\u043A\u0438 \u0441\u0442\u0440\u043E\u0433\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0432\u0430\u044E\u0442 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0435 boks \u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u043E\u0442 \u044F\u0437\u044B\u043A\u0430 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430.</p><p>\u0422\u0440\u0438 \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u044B\u0445 \u044F\u0449\u0438\u043A\u0430 \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \xAB\u041F\u0440\u043E\u0437\u0430\xBB, \xAB\u041F\u043E\u044D\u0437\u0438\u044F\xBB \u0438 \xAB\u041B\u044E\u0431\u0430\u044F\xBB, \u043A\u0430\u043A \u043E\u0434\u0438\u043D \u043E\u0442\u0432\u0435\u0442. \u0412\u043D\u0443\u0442\u0440\u0438 \u043B\u0430\u0442\u0443\u043D\u043D\u043E\u0439 \u0440\u0443\u0447\u043A\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u044F\u0449\u0438\u043A\u0430 \u0437\u0430\u0433\u043E\u0440\u0430\u0435\u0442\u0441\u044F \u0442\u0451\u043F\u043B\u044B\u0439 \u0441\u0432\u0435\u0442, \u0440\u044F\u0434\u043E\u043C \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043C\u0430\u0442\u043E\u0432\u0430\u044F \u0433\u0430\u043B\u043E\u0447\u043A\u0430. \u0414\u0435\u0440\u0435\u0432\u044F\u043D\u043D\u044B\u0439 \u0444\u0430\u0441\u0430\u0434 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u044B\u043C, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0438\u0441\u0445\u043E\u0434\u043D\u044B\u0435 \u0440\u0430\u0437\u043C\u0435\u0440, \u0446\u0432\u0435\u0442 \u0438 \u0444\u0430\u043A\u0442\u0443\u0440\u0443. \u0421\u0432\u0435\u0442 \u043D\u0435 \u0437\u0430\u043B\u0438\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u044C \u0438 \u0431\u043E\u043A\u043E\u0432\u0438\u043D\u044B. \u041A\u0430\u0436\u0434\u044B\u0439 \u0444\u0430\u0441\u0430\u0434 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0442\u043E\u0447\u043D\u044B\u043C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u043E\u043C \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u0441 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u043D\u043E\u0439 \u043A \u043D\u0435\u043C\u0443 \u0436\u0438\u0432\u043E\u0439 \u043F\u043E\u0434\u043F\u0438\u0441\u044C\u044E; \u043C\u0435\u0436\u0434\u0443 \u0440\u0430\u0437\u043D\u044B\u043C\u0438 \u0441\u0433\u0435\u043D\u0435\u0440\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C\u0438 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044F\u043C\u0438 \u043D\u0435\u0442 \u0440\u0430\u0441\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u044F. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u043E\u0441\u043D\u043E\u0432\u0430 \u0432\u0438\u0434\u043D\u0430 \u0434\u043E \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u0438 \u0441\u043B\u043E\u0451\u0432; \u0432\u043D\u0443\u0442\u0440\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u044F \u0447\u0438\u0441\u0442\u043E\u0439 \u0431\u0443\u043C\u0430\u0433\u0438. \u042D\u0442\u043E \u043C\u044F\u0433\u043A\u0430\u044F \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u0430\u044F \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u044F, \u0430 \u043D\u0435 \u0437\u0430\u043F\u0440\u0435\u0442 \u043D\u0430 \u0434\u0440\u0443\u0433\u0443\u044E \u0444\u043E\u0440\u043C\u0443 \u0438\u043B\u0438 \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u0444\u0438\u043B\u044C\u0442\u0440 \xAB\u0427\u0442\u043E \u043F\u043E\u0447\u0438\u0442\u0430\u0442\u044C\xBB.</p><p>\u041A\u043B\u0430\u0441\u0441\u0438\u043A\u0438 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u043C \u044F\u0437\u044B\u043A\u0430\u043C. \u041A\u043D\u0438\u0433\u0438 \u043E\u043F\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043F\u043E\u043B\u043A\u0438, \u0438\u043C\u0435\u043D\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u043C HTML, \u043F\u043E\u0440\u0442\u0440\u0435\u0442\u043D\u044B\u0435 \u0440\u0435\u0444\u0435\u0440\u0435\u043D\u0441\u044B \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u044B \u043A\u0430\u043A \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0432\u044E\u0440\u0430 \u0438\u043B\u0438 \u0442\u0438\u0441\u043D\u0435\u043D\u0438\u0435. \u0418\u0441\u0445\u043E\u0434\u043D\u044B\u0435 \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u044B; \u0440\u0435\u043F\u0440\u043E\u0434\u0443\u043A\u0446\u0438\u044F \u043D\u0435 \u0432\u044B\u0434\u0430\u0451\u0442\u0441\u044F \u0437\u0430 \u043D\u0435\u0438\u0437\u043C\u0435\u043D\u0451\u043D\u043D\u044B\u0439 \u0441\u043D\u0438\u043C\u043E\u043A. \u0422\u0435\u043A\u0441\u0442\u043E\u0432 \u0438 \u043E\u0442\u0440\u044B\u0432\u043A\u043E\u0432 \u0432\u043D\u0443\u0442\u0440\u0438 \u043D\u0435\u0442. \u0421\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u0430\u044F \u0447\u0430\u0441\u0442\u044C \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u0443\u0441\u0441\u043A\u043E\u044F\u0437\u044B\u0447\u043D\u044B\u0445 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0439 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0443\u0441\u0441\u043A\u043E\u043C. \u0410\u043B\u0435\u043A\u0441\u0435\u0439 \u041F\u0440\u043E\u0445\u043E\u0440\u043E\u0432, \u0414\u043C\u0438\u0442\u0440\u0438\u0439 \u0412\u043E\u0434\u0435\u043D\u043D\u0438\u043A\u043E\u0432 \u0438 \u0414\u0430\u0440\u044C\u044F \u041C\u0430\u043B\u044C\u043E-\u0421\u0443\u0431\u0431\u043E\u0442\u0438\u043D\u0430 \u0443\u0436\u0435 \u043F\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u043D\u0430 \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0435 \u043F\u043E \u0441\u043B\u043E\u0432\u0430\u043C \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0435\u0432\u044F\u0442\u044C \u2014 \u0440\u0435\u0434\u0430\u043A\u0446\u0438\u043E\u043D\u043D\u043E\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u0438\u0435 \u043F\u043E\u044D\u0442\u0430\u043C\u0438 \u0438 \u0430\u0432\u0442\u043E\u0440\u0430\u043C\u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u043E\u0439 \u043F\u0440\u043E\u0437\u044B, \u043D\u0435 \u043E\u0431\u044A\u0435\u043A\u0442\u0438\u0432\u043D\u044B\u0439 \u0440\u0435\u0439\u0442\u0438\u043D\u0433. \u041F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043E \u044D\u0442\u0438\u043C\u0438 \u0444\u043E\u0440\u043C\u0430\u043C\u0438; \u0431\u0438\u0431\u043B\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F \u0437\u0430\u043F\u0438\u0441\u0430\u043D\u044B \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u041F\u0440\u0435\u0436\u043D\u0438\u0435 \u043F\u0440\u0438\u043C\u0435\u0440\u044B \u0430\u0432\u0442\u043E\u0440\u043E\u0432, \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0445 \u043D\u0430 \u0440\u043E\u043C\u0430\u043D\u044B, \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0432\u044B\u0431\u043E\u0440\u0435, \u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0432 \u0438\u0441\u0442\u043E\u0440\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0437\u0430\u043F\u0438\u0441\u044F\u0445 \u043F\u0440\u043E\u0444\u0438\u043B\u044F. \u041D\u0430 \u0442\u043A\u0430\u043D\u0435\u0432\u044B\u0445 \u0438\u0437\u0434\u0430\u043D\u0438\u044F\u0445 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0447\u0451\u0440\u043D\u043E-\u0431\u0435\u043B\u044B\u0435 \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u0438; \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0441\u043D\u0438\u043C\u043E\u043A \u0414\u0430\u0440\u044C\u0438 \u043F\u0440\u0435\u0434\u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C. \u041F\u0440\u0438 \u043E\u0434\u043D\u043E\u043C \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C \u0441\u043A\u0440\u044B\u0442\u044B \u0438 \u043F\u0440\u0435\u0434\u043C\u0435\u0442\u044B, \u0438 \u0441\u0430\u043C \u0448\u0430\u0433; \u043F\u0440\u0435\u0436\u043D\u0438\u0435 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F.</p><p>\xAB\u041D\u0430\u0437\u0430\u0434\xBB \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043D\u0430 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0439 \u0448\u0430\u0433. \xAB\u041F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C\xBB \u043D\u0430 \u0430\u0432\u0442\u043E\u0440\u0430\u0445 \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043D\u043E\u0435. \xAB\u041F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443\xBB \u043D\u0430 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0432\u044B\u0432\u043E\u0434\u0438\u0442 \u043A \u0447\u0442\u0435\u043D\u0438\u044E. \xAB\u041B\u044E\u0431\u0430\u044F\xBB \u2014 \u043F\u043E\u043B\u043D\u043E\u0446\u0435\u043D\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442; \u043D\u043E\u0440\u043C\u044B \u043F\u043E \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0443 \u0430\u0432\u0442\u043E\u0440\u043E\u0432 \u043D\u0435\u0442. \u041E\u0434\u043D\u0430 \u043E\u0431\u044B\u0447\u043D\u0430\u044F \u0441\u0432\u0435\u0442\u043B\u0430\u044F \u043A\u043D\u043E\u043F\u043A\u0430 \u0432\u044B\u0441\u043E\u0442\u043E\u0439 56 CSS-\u043F\u0438\u043A\u0441\u0435\u043B\u0435\u0439 \u0437\u0430\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u0430 \u0441\u043D\u0438\u0437\u0443 \u044D\u043A\u0440\u0430\u043D\u0430 \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u043A\u0430\u043C\u0435\u0440\u044B. \u041C\u0435\u0442\u0430\u043B\u043B\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043F\u043B\u0430\u0448\u043A\u0438 \u0441 \u043A\u0440\u0435\u043F\u043B\u0435\u043D\u0438\u044F\u043C\u0438 \u0438 \u043A\u0440\u0443\u0433\u043B\u044B\u0435 \u043A\u043D\u043E\u043F\u043A\u0438 \u043C\u0435\u0436\u0434\u0443 \u043A\u043D\u0438\u0433\u0430\u043C\u0438 \u0443\u0431\u0440\u0430\u043D\u044B. \u0412\u043E\u0437\u0432\u0440\u0430\u0442 \u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432 \u0448\u0430\u043F\u043A\u0435; \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0445 \u043F\u043E\u043B\u043E\u043A \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u041D\u0438\u0436\u043D\u044F\u044F \u043A\u043D\u043E\u043F\u043A\u0430 \u0438 \u0448\u0430\u043F\u043A\u0430 \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u044E\u0442 \u0441\u0440\u0430\u0437\u0443 \u043F\u043E\u0441\u043B\u0435 \u0436\u0435\u0441\u0442\u0430: \u0437\u0430\u0449\u0438\u0442\u0430 \u043E\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0433\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u043D\u0430 \u043A\u043D\u0438\u0433\u0443 \u043D\u0435 \u0431\u043B\u043E\u043A\u0438\u0440\u0443\u0435\u0442 \u043D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u044E. \u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0436\u0435\u0441\u0442\u0430 \u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0438\u043D\u0435\u0440\u0446\u0438\u0438 \u043D\u0435 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u043A\u043D\u0438\u0433\u0438 \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C\u0438. \u0417\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0438 \u0438\u043C\u0435\u044E\u0442 \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u0435 \u043E\u0442\u0441\u0442\u0443\u043F\u044B \u043E\u0442 \u043D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u0438, \u043A\u0440\u0430\u0451\u0432 \u043A\u0430\u0434\u0440\u0430 \u0438 \u043C\u0435\u0431\u0435\u043B\u0438 \u0438 \u043D\u0435 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043A\u0430\u043C\u0435\u0440\u043E\u0439. \u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u043D\u044B\u0439 \u0444\u043E\u043A\u0443\u0441 \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442\u0441\u044F \u043C\u044F\u0433\u043A\u0438\u043C \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u043C \u0441\u0432\u0435\u0442\u043E\u043C \u0432\u043C\u0435\u0441\u0442\u043E \u043F\u0440\u044F\u043C\u043E\u0443\u0433\u043E\u043B\u044C\u043D\u043E\u0439 \u0440\u0430\u043C\u043A\u0438.</p><p>\u041C\u0438\u0440 \u043D\u0435 \u043F\u0435\u0440\u0435\u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u043C\u0435\u0436\u0434\u0443 \u043E\u0442\u0432\u0435\u0442\u0430\u043C\u0438. \u0411\u043E\u043A\u043E\u0432\u043E\u0439 \u043F\u0435\u0440\u0435\u043B\u0451\u0442 \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D\u043D\u044B\u0435 \u043E\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0431\u0435\u0437 \u043F\u0440\u0435\u0436\u043D\u0435\u0433\u043E \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u0430 \u043C\u0430\u0441\u0448\u0442\u0430\u0431\u0430; \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u043D\u0438\u0435 \u0438 resize \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0438\u0437 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u043C\u0430\u0442\u0440\u0438\u0446\u044B. \u0421\u0442\u0432\u043E\u0440\u043A\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u0430\u043F\u043E\u043C \u0438\u043B\u0438 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u044B\u043C \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u043C \u0436\u0435\u0441\u0442\u043E\u043C. \u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435 \u0431\u043B\u043E\u043A\u0438\u0440\u0443\u0435\u0442\u0441\u044F \u043D\u0430 \u043F\u0435\u0440\u0435\u043B\u0451\u0442\u0435, \u043D\u043E \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u043C \u043F\u0440\u0438 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043F\u0440\u043E\u043A\u0440\u0443\u0442\u043A\u0435. \u041A\u0430\u0434\u0440 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0432\u0438\u0434\u0438\u043C\u0443\u044E \u0432\u044B\u0441\u043E\u0442\u0443 Safari \u0438 \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430; \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C\u044B \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0432\u044B\u0448\u0435 \u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u043E\u0439 \u043A\u043D\u043E\u043F\u043A\u0438, \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u043C\u0438\u043D\u0438\u043C\u0443\u043C 12 \u044D\u043A\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0438\u043A\u0441\u0435\u043B\u0435\u0439. \u041D\u0438\u0437\u043A\u043E\u0435 \u043E\u043A\u043D\u043E \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u043A\u0430\u043C\u0435\u0440\u044B \u0436\u0435\u0441\u0442\u043E\u043C, \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u043C\u0438 \u0438\u043B\u0438 \u0444\u043E\u043A\u0443\u0441\u043E\u043C. \u041D\u0430 \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0445 \u043F\u043E\u043B\u043A\u0430\u0445 \u043F\u043E\u0440\u0442\u0440\u0435\u0442\u043D\u044B\u0439 \u043A\u0430\u0434\u0440 \u0441\u043B\u0435\u0434\u0443\u0435\u0442 \u0448\u0438\u0440\u0438\u043D\u0435; \u0432 \u043D\u0438\u0437\u043A\u043E\u043C \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u043E\u043C \u043E\u043A\u043D\u0435 \u043C\u0430\u0441\u0448\u0442\u0430\u0431 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D \u0432\u044B\u0441\u043E\u0442\u043E\u0439 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0440\u044F\u0434\u0430, \u0447\u0442\u043E\u0431\u044B \u043A\u0430\u043C\u0435\u0440\u0430 \u043D\u0435 \u043F\u0440\u0438\u0437\u0435\u043C\u043B\u044F\u043B\u0430\u0441\u044C \u043D\u0438\u0436\u0435 \u043A\u043D\u0438\u0433. \u041D\u0435\u043F\u0440\u0435\u0440\u044B\u0432\u043D\u0430\u044F \u0442\u0435\u043A\u0441\u0442\u0443\u0440\u0430 \u0441\u0442\u0435\u043D\u044B \u0438 \u043C\u044F\u0433\u043A\u0438\u0439 \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u0443 \u043F\u0440\u0430\u0432\u043E\u0433\u043E \u043A\u0440\u0430\u044F \u043A\u043E\u043C\u043D\u0430\u0442\u044B \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u0441\u0442\u044B\u043A \u043D\u0430\u0434 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0449\u0435\u0439.</p><p>\u0410\u043D\u0438\u043C\u0430\u0446\u0438\u0438 \u0436\u0451\u043B\u0442\u043E\u0439 \u043B\u0435\u043D\u0442\u044B \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0443\u0431\u0440\u0430\u043D\u044B \u0438\u0437 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0430 \u0438 \u0441\u043C\u0435\u043D\u044B \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u0439: \u0435\u0451 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0431\u0443\u0434\u0435\u0442 \u043F\u0440\u043E\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0442\u044C\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u041D\u0435\u0442 \u043F\u0440\u043E\u043B\u0451\u0442\u0430 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430 \u0438 \u0437\u0430\u0434\u0435\u0440\u0436\u0430\u043D\u043D\u043E\u0433\u043E \u043F\u043E\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u043E\u0442\u043C\u0435\u0442\u043A\u0438. \u0414\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u043A\u0430\u043C\u0435\u0440\u044B \u0438 \u0441\u0442\u0432\u043E\u0440\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F; \u043F\u0440\u0438 \u0432\u044B\u0431\u043E\u0440\u0435 \u0444\u043E\u0440\u043C\u044B \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0439 \u0441\u0432\u0435\u0442 \u0438 \u043E\u0442\u043C\u0435\u0442\u043A\u0430. \u041E\u0442\u0432\u0435\u0442 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0434\u043E \u044D\u0444\u0444\u0435\u043A\u0442\u0430; reduced motion \u0441\u0440\u0430\u0437\u0443 \u0441\u0442\u0430\u0432\u0438\u0442 \u0441\u0446\u0435\u043D\u0443 \u0432 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435. \u0414\u0438\u0430\u0433\u043D\u043E\u0441\u0442\u0438\u043A\u0430 rAF \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u043F\u043E\u0442\u043E\u043A, \u0430 \u043D\u0435 \u043A\u0430\u0436\u0434\u044B\u0439 GPU-\u043A\u0430\u0434\u0440 \u0438\u043B\u0438 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u0443\u044E \u0447\u0430\u0441\u0442\u043E\u0442\u0443 \u043D\u0430 \u0432\u0441\u0435\u0445 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430\u0445.</p><p>\u041D\u043E\u0432\u044B\u0435 \u0441\u0446\u0435\u043D\u044B \u0431\u0435\u0437 \u043F\u043B\u0430\u0448\u0435\u043A, \u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0443\u0433\u043B\u0443\u0431\u043B\u0435\u043D\u0438\u044F, \u0442\u043E\u0447\u043D\u044B\u0435 \u0444\u0430\u0441\u0430\u0434\u044B, \u043F\u0440\u043E\u043C\u043F\u0442\u044B \u0432\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u043E\u0433\u043E imagegen, \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0438 \u0433\u0435\u043E\u043C\u0435\u0442\u0440\u0438\u044F \u2014 \u0432 assets/onboarding/integrated-v30. \u041A\u043E\u043C\u043D\u0430\u0442\u0430 \u0438 \u0441\u0442\u0432\u043E\u0440\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 opening-prefixed \u0437\u0430\u043F\u0438\u0441\u0438 \u0432 integrated-v28; \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0435 \u043C\u043E\u0434\u0443\u043B\u0438 \u2014 \u0432 wide-v26, \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043F\u0435\u0440\u0435\u043F\u043B\u0451\u0442\u044B \u2014 \u0432 books-v25, \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B\u044B \u2014 \u0432 modern-v29. \u0421\u043D\u0438\u043C\u043E\u043A \u0414\u0430\u0440\u044C\u0438, \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B \u0438 \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u2014 \u0432 assets/authors/contemporary-v29; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0435\u0436\u043D\u0438\u0435 \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u0438 \u2014 \u0432 contemporary-v27, \u043D\u043E\u0432\u044B\u0435 \u043F\u043E\u0440\u0442\u0440\u0435\u0442\u044B \u0438 \u0431\u0438\u0431\u043B\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F \u2014 \u0432 contemporary-v31. \u0412 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u043C \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0435 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0447\u0435\u0442\u044B\u0440\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0445 boks; \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u0442\u0435\u043A\u0441\u0442\u044B \u0438 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u044B \u0442\u0443\u0434\u0430 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u043B\u0438\u0441\u044C. \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 Series \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0445 \u0430\u0432\u0442\u043E\u0440\u043E\u0432 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u043C \u043F\u0440\u0435\u0432\u044C\u044E \u043A\u043E\u043C\u043D\u0430\u0442\u044B. \u0417\u0434\u0435\u0441\u044C \u043D\u0435\u0442 XP, \u0432\u0430\u043B\u044E\u0442\u044B, \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u0430 \u043F\u043E\u043D\u044F\u0442\u043E\u0433\u043E \u0432\u043A\u0443\u0441\u0430 \u0438\u043B\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u043F\u043E\u0434\u043F\u0438\u0441\u043E\u043A.</p>'},{label:"03 / \u041E\u0442 \u043E\u0442\u0432\u0435\u0442\u0430 \u043A \u043F\u043E\u0434\u0431\u043E\u0440\u0443",title:"\u0421\u0438\u043C\u043F\u0430\u0442\u0438\u044F, \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0430 \u0438 \u0447\u0442\u0435\u043D\u0438\u0435 \u2014 \u0440\u0430\u0437\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435.",html:'<div class="scenario-table"><table><thead><tr><th>\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435</th><th>\u041A\u0430\u043A \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F</th><th>\u0427\u0442\u043E \u043D\u0435 \u043F\u0440\u0435\u0434\u043F\u043E\u043B\u0430\u0433\u0430\u0435\u0442\u0441\u044F</th></tr></thead><tbody><tr><td>\u041E\u0442\u043C\u0435\u0442\u0438\u043B \u0431\u043B\u0438\u0437\u043A\u043E\u0433\u043E \u0430\u0432\u0442\u043E\u0440\u0430</td><td>\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u0430\u043A \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u044F\u0432\u043D\u0430\u044F \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u044F; \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 boks \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043C\u044F\u0433\u043A\u043E\u0435 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0435 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E.</td><td>\u042D\u0442\u043E \u043D\u0435 \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0430, \u043B\u0430\u0439\u043A \u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u044F, \u043F\u0440\u043E\u0447\u0442\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u043C\u0435\u0441\u0442\u043E \u0432 \u043B\u0438\u0447\u043D\u043E\u043C \u0440\u0435\u0439\u0442\u0438\u043D\u0433\u0435.</td></tr><tr><td>\u041F\u043E\u0434\u043F\u0438\u0441\u0430\u043B\u0441\u044F</td><td>\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0441\u0432\u044F\u0437\u044C \u0441 \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u043C byline, \u0442\u0440\u0435\u0431\u0443\u044E\u0449\u0430\u044F \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430.</td><td>\u0421\u0438\u043C\u043F\u0430\u0442\u0438\u044F \u0432 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0435 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u044D\u0442\u0443 \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u044E \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.</td></tr><tr><td>\u0412\u0441\u043F\u043E\u043C\u043D\u0438\u043B \u043A\u043D\u0438\u0433\u0443 \u0438\u043B\u0438 \u0430\u0432\u0442\u043E\u0440\u0430</td><td>\u0422\u0435\u043A\u0441\u0442 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0432 \u0435\u0433\u043E \u0431\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u0438.</td><td>\u0421\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C \u043D\u0435 \u0441\u043E\u0437\u0434\u0430\u0451\u0442 \u043A\u0430\u0442\u0430\u043B\u043E\u0436\u043D\u044B\u0439 bok, \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u043E\u0435 \u0447\u0442\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u043D\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0435 \u043F\u043E\u043D\u0438\u043C\u0430\u043D\u0438\u0435 \u0430\u043B\u0433\u043E\u0440\u0438\u0442\u043C\u0430.</td></tr><tr><td>\u0412\u044B\u0431\u0440\u0430\u043B \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435</td><td>\u0412\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0435 \u043C\u044F\u0433\u043A\u043E\u0435 \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u043D\u0430 \u0441\u0435\u0430\u043D\u0441; \u0444\u043E\u0440\u043C\u0430, \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u044F\u0437\u044B\u043A\u0438 \u0437\u0430\u0434\u0430\u044E\u0442 \u0441\u0442\u0440\u043E\u0433\u0438\u0439 \u0434\u043E\u043F\u0443\u0441\u043A.</td><td>\u042D\u0442\u043E \u043D\u0435 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u044B\u0439 \u0432\u043A\u0443\u0441. \u041D\u0443\u043B\u0435\u0432\u043E\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043D\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u044F\u0435\u0442\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u043E.</td></tr><tr><td>\u0427\u0438\u0442\u0430\u0435\u0442 \u0438 \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 boks</td><td>\u041B\u0430\u0439\u043A\u0438, foreground time, \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0438 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u0441\u0435\u0430\u043D\u0441\u044B \u0434\u0430\u044E\u0442 \u0441\u0432\u043E\u0438 \u0444\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F.</td><td>\u041E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u0435\u0440\u0434\u0435\u0447\u043A\u0430 \u0441\u0430\u043C\u0438 \u043F\u043E \u0441\u0435\u0431\u0435 \u043D\u0435 \u0434\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435.</td></tr></tbody></table></div><p>\u0412 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0435 \u0447\u0435\u0442\u044B\u0440\u043D\u0430\u0434\u0446\u0430\u0442\u044C boks \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0445 byline; \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0445 \u0438\u043C\u0451\u043D \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u044B \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u0430\u043A \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043E\u0431\u0440\u0435\u0437\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u0442\u0440\u0451\u0445. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u0442\u043E\u0436\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043C\u044F\u0433\u043A\u043E \u0438 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u0441\u0442\u0440\u043E\u0433\u0438\u0439 \u0434\u043E\u043F\u0443\u0441\u043A. \u041C\u044F\u0433\u043A\u0438\u0439 \u0432\u0435\u0441 seed 2,5 \u0437\u0430\u0442\u0443\u0445\u0430\u0435\u0442 \u043F\u043E \u043C\u0435\u0440\u0435 \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u044F \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u0447\u0442\u0435\u043D\u0438\u044F; \u044D\u0442\u043E \u0434\u0435\u043C\u043E\u043D\u0441\u0442\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u044B\u0439 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440, \u0430 \u043D\u0435 \u0434\u043E\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0435 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u043E \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0430\u0446\u0438\u0439. \u0420\u0430\u0437\u043D\u043E\u043E\u0431\u0440\u0430\u0437\u0438\u0435 \u043B\u0435\u043D\u0442\u044B \u0438 \u0441\u0442\u0440\u043E\u0433\u0438\u0435 \u044F\u0437\u044B\u043A\u043E\u0432\u044B\u0435/\u0440\u0435\u0434\u0430\u043A\u0446\u0438\u043E\u043D\u043D\u044B\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F. \u0423 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0435\u0433\u043E \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435. \u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u044F\u0432\u043D\u044B\u043C \u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435\u043C, \u043D\u0430\u0447\u0430\u0442\u044B\u043C \u0443\u0436\u0435 \u043F\u043E\u0441\u043B\u0435 \u0432\u0445\u043E\u0434\u0430; \u044D\u0442\u043E \u043D\u0430\u043C\u0435\u0440\u0435\u043D\u0438\u0435 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u043F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0435.</p><p>\u0422\u0435\u043A\u0441\u0442\u044B \u0441 byline \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u043E\u0432 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D\u044B \u043E\u0431\u0449\u0438\u043C \u0438\u0437\u0434\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u043C \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u043E\u043C, \u043D\u043E \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0430 \u043D\u0435 \u0434\u043E\u043B\u0436\u043D\u0430 \u0430\u0434\u0440\u0435\u0441\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u044D\u0442\u043E\u043C\u0443 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0443. \u0420\u0430\u0431\u043E\u0447\u0435\u043C\u0443 \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u0443 \u043D\u0443\u0436\u043D\u044B \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u043D\u044B\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u044B \u0438 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u044B \u043A\u0430\u043D\u0434\u0438\u0434\u0430\u0442\u043E\u0432. \u0412\u044B\u0434\u0430\u043D\u043D\u0430\u044F \u043B\u0435\u043D\u0442\u0430 \u0438 \u0432\u0435\u0440\u0441\u0438\u0438 \u0440\u0430\u043D\u0436\u0438\u0440\u0443\u044E\u0449\u0438\u0445 \u0432\u0445\u043E\u0434\u043E\u0432 \u0434\u043E\u043B\u0436\u043D\u044B \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442\u044C \u0447\u0435\u0440\u0435\u0437 \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 Worker.</p>'},{label:"04 / \u041D\u0430 \u044D\u0442\u0443 \u043F\u0430\u0443\u0437\u0443",title:"\u041F\u043E\u0433\u0440\u0443\u0441\u0442\u0438\u0442\u044C. \u041F\u043E\u0432\u0435\u0441\u0435\u043B\u0438\u0442\u044C\u0441\u044F. \u041F\u043E\u0434\u0443\u043C\u0430\u0442\u044C.",html:'<div class="concept-grid"><article class="principle"><span class="pill-label">\u041F\u043E\u0433\u0440\u0443\u0441\u0442\u0438\u0442\u044C</span><h3>\u041F\u043E\u0431\u044B\u0442\u044C \u0441 \u0447\u0443\u0432\u0441\u0442\u0432\u043E\u043C</h3><p>\u0422\u0438\u0445\u0430\u044F \u043F\u0435\u0447\u0430\u043B\u044C, \u043F\u0430\u043C\u044F\u0442\u044C, \u043D\u0435\u0436\u043D\u043E\u0441\u0442\u044C \u0438\u043B\u0438 \u0443\u0442\u0440\u0430\u0442\u0430. \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u0445\u043E\u0442\u0435\u0442\u044C \u0433\u0440\u0443\u0441\u0442\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430, \u043D\u0435 \u0440\u0430\u0441\u0441\u043A\u0430\u0437\u044B\u0432\u0430\u044F \u043D\u0438\u0447\u0435\u0433\u043E \u043E \u0441\u0432\u043E\u0451\u043C \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0438.</p></article><article class="principle"><span class="pill-label">\u041F\u043E\u0432\u0435\u0441\u0435\u043B\u0438\u0442\u044C\u0441\u044F</span><h3>\u0423\u043B\u044B\u0431\u043D\u0443\u0442\u044C\u0441\u044F \u0447\u0435\u043C\u0443-\u0442\u043E \u0442\u043E\u0447\u043D\u043E\u043C\u0443</h3><p>\u042E\u043C\u043E\u0440, \u0438\u0440\u043E\u043D\u0438\u044F, \u0438\u0433\u0440\u0430 \u0438 \u043D\u0435\u043E\u0436\u0438\u0434\u0430\u043D\u043D\u044B\u0439 \u043F\u043E\u0432\u043E\u0440\u043E\u0442. \u041B\u0451\u0433\u043A\u043E\u0441\u0442\u044C \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430.</p></article><article class="principle"><span class="pill-label">\u041F\u043E\u0434\u0443\u043C\u0430\u0442\u044C</span><h3>\u0423\u043D\u0435\u0441\u0442\u0438 \u0441 \u0441\u043E\u0431\u043E\u0439 \u0432\u043E\u043F\u0440\u043E\u0441</h3><p>\u041D\u043E\u0432\u044B\u0439 \u0432\u0437\u0433\u043B\u044F\u0434, \u0441\u043B\u043E\u0436\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440 \u0438\u043B\u0438 \u043C\u044B\u0441\u043B\u044C, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u0442\u0440\u043E\u043A\u0438.</p></article></div><p>\xAB\u0427\u0442\u043E \u043F\u043E\u0447\u0438\u0442\u0430\u0442\u044C\xBB \u043D\u0430 \u0433\u043B\u0430\u0432\u043D\u043E\u0439 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0430\u043D\u0435\u043B\u044C \u0432\u043D\u0443\u0442\u0440\u0438 \u044D\u043A\u0440\u0430\u043D\u0430 boks, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0432\u043D\u0443\u0442\u0440\u0438 \u0440\u0430\u043C\u043A\u0438 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430 \u043D\u0430 \u0431\u043E\u043B\u044C\u0448\u043E\u043C \u044D\u043A\u0440\u0430\u043D\u0435: \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435, \u043F\u0440\u043E\u0437\u0430 \u0438\u043B\u0438 \u043F\u043E\u044D\u0437\u0438\u044F, \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0438 \u0438\u043B\u0438 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435. \u0412 \u043F\u0430\u043D\u0435\u043B\u0438 \u0447\u0442\u0435\u043D\u0438\u044F \u044D\u0442\u043E\u0433\u043E \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u0430 \u043D\u0435\u0442. \u041A\u0440\u0443\u0433\u043B\u0430\u044F \u0438\u043B\u043B\u044E\u0441\u0442\u0440\u0430\u0446\u0438\u044F \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0440\u0430\u0437\u043C\u044B\u0442\u044B\u0439 \u0444\u043E\u043D; \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0434\u0435\u043B\u0438\u0442\u0435\u043B\u044F \u043D\u0435\u0442. \u0418\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0447\u0435\u0440\u043D\u043E\u0432\u044B\u0435. \xAB\u041F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C\xBB \u0441\u0440\u0430\u0437\u0443 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u0431\u043E\u043A. \u0410\u043D\u0438\u043C\u0430\u0446\u0438\u044F \u043B\u0435\u043D\u0442\u044B \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0443\u0431\u0440\u0430\u043D\u0430: \u043D\u043E\u0432\u043E\u0435 \u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u0440\u0430\u0437\u0443; \u0433\u0440\u0430\u043D\u0438\u0446\u0430 \u0433\u043E\u0441\u0442\u044F \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432 \u0441\u0438\u043B\u0435. \u0417\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A. \u041D\u0443\u043B\u0435\u0432\u043E\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043D\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u044F\u0435\u0442\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u043E: \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u044F\u0442\u044C \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u043E\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u0435.</p><p>\u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u2014 \u043C\u044F\u0433\u043A\u043E\u0435 \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u0435; \u0444\u043E\u0440\u043C\u0430 \u0438 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u2014 \u0441\u0442\u0440\u043E\u0433\u0438\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0433\u0440\u0443\u043F\u043F \u0430\u0432\u0442\u043E\u0440\u043E\u0432 \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u044E\u0442\u0441\u044F. \u0412 \u0434\u0430\u043D\u043D\u043E\u043C \u043F\u0440\u0438\u043C\u0435\u0440\u0435 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0445 \u0442\u0435\u043A\u0441\u0442\u043E\u0432 \u043D\u0435\u0442, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D \u043D\u0435 \u0432\u044B\u0434\u0430\u0451\u0442 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0443 \u0437\u0430 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u043F\u043E\u0434\u0431\u043E\u0440. \u0412\u0441\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0442\u0440\u0438\u0434\u0446\u0430\u0442\u0438 \u043C\u0438\u043D\u0443\u0442 \u0431\u0435\u0437 \u0447\u0442\u0435\u043D\u0438\u044F.</p><p>\u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043C\u044F\u0433\u043A\u043E \u043F\u043E \u0440\u0435\u0434\u0430\u043A\u0446\u0438\u043E\u043D\u043D\u044B\u043C \u043C\u0435\u0442\u043A\u0430\u043C. \u0415\u0441\u043B\u0438 \u0442\u043E\u0447\u043D\u043E\u0433\u043E \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u044F \u043D\u0435\u0442, \u0430\u043B\u0433\u043E\u0440\u0438\u0442\u043C \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0432\u043D\u0443\u0442\u0440\u0438 \u0437\u0430\u0434\u0430\u043D\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u044B, \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0445 \u0433\u0440\u0443\u043F\u043F \u0438 \u044F\u0437\u044B\u043A\u043E\u0432. \u0416\u0451\u0441\u0442\u043A\u0438\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u0441\u0430\u043C\u0438 \u043D\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u044F\u044E\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435\u0432\u043A\u0443\u0441\u0438\u0435 \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043D\u043E\u0433\u043E \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u0435\u043C.</p>'},{label:"05 / \u0412\u0445\u043E\u0434\u044B \u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F",title:"\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435 \u0432\u0445\u043E\u0434\u0430.",html:'<div class="scenario-table"><table><thead><tr><th>\u0412\u0445\u043E\u0434</th><th>\u041F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435</th></tr></thead><tbody><tr><td>\u041F\u0435\u0440\u0432\u044B\u0439 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0432\u0438\u0437\u0438\u0442</td><td>\u041A\u043E\u043C\u043D\u0430\u0442\u0430 \u2192 \u044F\u0437\u044B\u043A\u0438 \u2192 \u0444\u043E\u0440\u043C\u0430 \u2192 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0438 \u2192 \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u0438\u043A\u0438 \u2192 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u0441 Series, \u043F\u043E\u0447\u0442\u043E\u0439 \u0438 \u0430\u0444\u0438\u0448\u0435\u0439 \u2192 \u043F\u0435\u0440\u0432\u044B\u0439 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0439 bok. \u0410\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0435 \u0448\u0430\u0433\u0438 \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C; \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u043F\u0440\u044F\u043C\u043E\u0439 \u0432\u044B\u0445\u043E\u0434 \u043A \u0447\u0442\u0435\u043D\u0438\u044E. <button data-scenario="home">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr><tr><td>\u041F\u0440\u044F\u043C\u0430\u044F \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 bok</td><td>\u041E\u0431\u0435\u0449\u0430\u043D\u043D\u043E\u0435 \u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u043E\u043D\u0431\u043E\u0440\u0434\u0438\u043D\u0433\u0430 \u043F\u043E\u0432\u0435\u0440\u0445 \u043D\u0435\u0433\u043E. <button data-scenario="direct">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr><tr><td>\u0421\u0441\u044B\u043B\u043A\u0430 \u043A \u0430\u0432\u0442\u043E\u0440\u0443</td><td>\u0410\u0432\u0442\u043E\u0440 \u0438 \u0435\u0433\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0442\u0435\u043A\u0441\u0442\u044B. \u0427\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0435 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u043D\u0435 \u043F\u043E\u0434\u043C\u0435\u043D\u044F\u0435\u0442 \u044D\u0442\u043E\u0442 \u0432\u0445\u043E\u0434. <button data-scenario="author">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr><tr><td>\u041D\u0435\u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0435 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E</td><td>\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0432\u044B\u0431\u043E\u0440, \u044D\u0442\u0430\u043F \u0438 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043A\u0430\u043C\u0435\u0440\u044B; \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0431\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u043F\u043E\u0437\u0436\u0435 \u0432 \u043F\u0440\u043E\u0444\u0438\u043B\u0435. <button data-scenario="onboarding">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr><tr><td>\u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C</td><td>\u0417\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0435 \u0438\u043B\u0438 \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0435 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u043D\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438. \u0420\u0430\u043D\u0435\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 bok \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043C\u0435\u0441\u0442\u043E. <button data-scenario="returning">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr><tr><td>\u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435</td><td>\u041B\u0438\u0447\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0438 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0435 \u043D\u0430\u043C\u0435\u0440\u0435\u043D\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F. \u041D\u043E\u0432\u044B\u0439 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u043D\u0430\u0441\u043B\u0435\u0434\u0443\u0435\u0442 \u0441\u0432\u043E\u0438 \u043E\u0442\u0432\u0435\u0442\u044B; \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043D\u0435 \u0442\u0435\u0440\u044F\u0435\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0439 seed \u0438\u0437-\u0437\u0430 \u0433\u043E\u0441\u0442\u0435\u0432\u043E\u0433\u043E \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0430. <button data-scenario="account">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></td></tr></tbody></table></div><p>\u041D\u0430 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043E\u0431\u043B\u043E\u0436\u043A\u0435 \u043D\u0435\u0442 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u044F \u0438\u043B\u0438 \u043F\u043B\u0430\u0448\u043A\u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u044F. \u0422\u0451\u043F\u043B\u043E\u0435 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u043F\u0435\u0440\u0432\u043E\u043C\u0443 \u043F\u043E\u043B\u0435\u0437\u043D\u043E\u043C\u0443 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0443. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438 \u043D\u0435 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0432 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0438. \u041B\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043D\u044B\u0439 byline \u0438 @handle \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0440\u0430\u0437\u043D\u044B\u043C\u0438 \u0438\u0434\u0435\u043D\u0442\u0438\u0447\u043D\u043E\u0441\u0442\u044F\u043C\u0438. \u041C\u0430\u0440\u0448\u0440\u0443\u0442 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u044E\u0449\u0435\u0433\u043E \u0430\u0432\u0442\u043E\u0440\u0430 \u0432 \u043A\u0430\u0431\u0438\u043D\u0435\u0442 \u2014 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0446\u0435\u043D\u0430\u0440\u0438\u0439.</p>'},{label:"06 / \u041F\u0440\u0438\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435 \u0432 \u0430\u043A\u043A\u0430\u0443\u043D\u0442",title:"\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u0440\u0438\u0447\u0438\u043D\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C.",html:'<p>\u0412\u044B\u0431\u043E\u0440 \u0431\u043B\u0438\u0437\u043A\u0438\u0445 \u0430\u0432\u0442\u043E\u0440\u043E\u0432, \u043B\u0438\u0447\u043D\u0430\u044F \u043F\u043E\u043B\u043A\u0430 \u0438 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0435 \u0432\u043E\u0441\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0433\u043E\u0441\u0442\u044E \u0431\u0435\u0437 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438. \u041D\u0430 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u043C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0437\u0443 \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0447\u0442\u0435\u043D\u0438\u044E; \u043D\u0430 \u043E\u0431\u043E\u0438\u0445 \u0430\u0432\u0442\u043E\u0440\u0441\u043A\u0438\u0445 \u0448\u0430\u0433\u0430\u0445 \u2014 \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0432\u044B\u0431\u043E\u0440. \u0413\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0447\u0438\u0442\u0430\u0442\u044C bok \u0438 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0438, \u0430 \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u044F \u0431\u0435\u0437 \u043F\u043E\u0447\u0442\u044B. \u041F\u043E\u043B\u044F \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u044F \u0434\u043E \u0432\u0445\u043E\u0434\u0430 \u043D\u0435\u0442. \u041B\u0430\u0439\u043A, \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u0438 \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0430 \u0442\u0440\u0435\u0431\u0443\u044E\u0442 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430 \u0438\u043C\u0435\u043D\u043D\u043E \u0432 \u043C\u043E\u043C\u0435\u043D\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u041F\u043E\u043B\u044C\u0437\u0430 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u0430: \u043B\u044E\u0431\u0438\u043C\u043E\u0435 \u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0441 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u0435\u043C.</p><div class="scenario-table"><table><thead><tr><th>\u0413\u0440\u0430\u043D\u0438\u0446\u0430</th><th>\u0427\u0442\u043E \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442</th><th>\u0427\u0442\u043E \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E</th></tr></thead><tbody><tr><td>\u041F\u043E\u0441\u043B\u0435 5 \u0440\u0430\u0437\u043D\u044B\u0445 \u0431\u043E\u043A\u043E\u0432</td><td>\u041D\u0435\u0431\u043E\u043B\u044C\u0448\u043E\u0435 \u043F\u0440\u0438\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435 \u043C\u0435\u0436\u0434\u0443 \u0431\u043E\u043A\u0430\u043C\u0438: \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C 10 \u0431\u0435\u0437 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430.</td><td>\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435 \u0447\u0442\u0435\u043D\u0438\u044F \u043E\u0434\u043D\u0438\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C. <button data-scenario="fifth">\u041F\u043E\u0441\u043B\u0435 \u043F\u044F\u0442\u0438 \u2192</button></td></tr><tr><td>\u041F\u043E\u0441\u043B\u0435 10</td><td>\u0421\u043F\u043E\u043A\u043E\u0439\u043D\u043E\u0435 \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u0435: \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043F\u044F\u0442\u044C; \u0434\u0430\u043B\u044C\u0448\u0435 \u043F\u043E\u043D\u0430\u0434\u043E\u0431\u0438\u0442\u0441\u044F email.</td><td>\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435 \u0431\u0435\u0437 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0432\u0445\u043E\u0434\u0430. <button data-scenario="tenth">\u041F\u043E\u0441\u043B\u0435 \u0434\u0435\u0441\u044F\u0442\u0438 \u2192</button></td></tr><tr><td>\u041F\u043E\u0441\u043B\u0435 15</td><td>\u0412\u0445\u043E\u0434 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0434 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0435\u043C \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u043E\u0433\u043E \u043D\u043E\u0432\u043E\u0433\u043E \u0431\u043E\u043A\u0430.</td><td>\u0422\u0435\u043A\u0443\u0449\u0438\u0439 \u0431\u043E\u043A \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043D\u0435\u043C\u0443. <button data-scenario="limit">\u0413\u0440\u0430\u043D\u0438\u0446\u0430 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u2192</button></td></tr></tbody></table></div><p>\u0421\u0447\u0451\u0442\u0447\u0438\u043A \u0441\u0447\u0438\u0442\u0430\u0435\u0442 <strong>\u0440\u0430\u0437\u043D\u044B\u0435 \u0431\u043E\u043A\u0438 \u0441 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u044B\u043C \u0432\u0440\u0435\u043C\u0435\u043D\u0435\u043C \u0447\u0442\u0435\u043D\u0438\u044F \u0432 foreground</strong> \u043F\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u043C\u0443 \u043F\u0440\u0430\u0432\u0438\u043B\u0443. \u041E\u043D \u043D\u0435 \u0440\u0430\u0432\u0435\u043D \u0441\u0432\u0430\u0439\u043F\u0430\u043C, \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F\u043C \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0438\u043B\u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0443 \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u043E\u0447\u0442\u0435\u043D\u0438\u0439. \u041E\u0434\u0438\u043D \u0431\u043E\u043A \u043D\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u0443\u0435\u0442 \u043B\u0438\u043C\u0438\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E. \u041F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u043D\u0435 \u043E\u0431\u043D\u0443\u043B\u044F\u0435\u0442 \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u0443\u044E \u0433\u0440\u0430\u043D\u0438\u0446\u0443.</p><p>\u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0432\u0430\u0436\u043D\u043E\u0441\u0442\u0438: \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u043D\u0430 \u0433\u0440\u0430\u043D\u0438\u0446\u0435 \u2192 \u0432\u0445\u043E\u0434 \u0440\u0430\u0434\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u2192 \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u0435 10/5 \u2192 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u2192 \u043E\u0431\u0440\u0430\u0442\u043D\u0430\u044F \u0441\u0432\u044F\u0437\u044C. \u0417\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u043E\u043A\u043D\u0430 \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445. \u041C\u044B \u043D\u0435 \u043E\u0431\u0435\u0449\u0430\u0435\u043C \xAB\u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0432\u0430\u0448\u0438 \u043B\u0430\u0439\u043A\u0438\xBB \u0433\u043E\u0441\u0442\u044E, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0435\u0449\u0451 \u043D\u0435 \u043C\u043E\u0433 \u0438\u0445 \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C; \u0433\u043E\u0432\u043E\u0440\u0438\u043C \u043E \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0439 \u0438\u0441\u0442\u043E\u0440\u0438\u0438 \u0438 \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F\u0445.</p>'},{label:"07 / \u0412\u0445\u043E\u0434 \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435",title:"\u0412\u0435\u0440\u043D\u0443\u0442\u044C \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u0442\u0443\u0434\u0430, \u043E\u0442\u043A\u0443\u0434\u0430 \u043E\u043D \u043F\u0440\u0438\u0448\u0451\u043B.",html:'<p>\u0414\u043B\u044F \u043D\u043E\u0432\u043E\u0433\u043E \u0438 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430 \u2014 \u043E\u0434\u0438\u043D \u043F\u0443\u0442\u044C \u043F\u043E \u043F\u043E\u0447\u0442\u0435 \u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043E\u043A \xAB\u0412\u043E\u0439\u0442\u0438\xBB \u0441 \u043F\u0440\u0438\u0447\u0438\u043D\u043E\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u041E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u043A\u043D\u043E\u043F\u043A\u0438 \xAB\u0423 \u043C\u0435\u043D\u044F \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u0430\u043A\u043A\u0430\u0443\u043D\u0442\xBB \u043D\u0435\u0442. \u041F\u0430\u0440\u043E\u043B\u044F \u043D\u0435\u0442: \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 boks \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 magic link \u0438 \u0448\u0435\u0441\u0442\u0438\u0437\u043D\u0430\u0447\u043D\u044B\u0439 \u043A\u043E\u0434. \u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0438 \u043F\u043E\u0434\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F @handle; \u043F\u043E\u043B\u043D\u043E\u0435 \u0438\u043C\u044F \u043D\u0435 \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044F.</p><div class="concept-grid"><article class="principle"><span class="pill-label">\u041B\u0430\u0439\u043A</span><h3>\u0422\u043E \u0436\u0435 \u0441\u0435\u0440\u0434\u0435\u0447\u043A\u043E</h3><p>\u041F\u043E\u0441\u043B\u0435 \u0443\u0441\u043F\u0435\u0448\u043D\u043E\u0433\u043E \u0432\u0445\u043E\u0434\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437. \u0411\u043E\u043A \u0438 \u043C\u0435\u0441\u0442\u043E \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F. <button data-scenario="like">\u041F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u2192</button></p></article><article class="principle"><span class="pill-label">\u041F\u043E\u0434\u043F\u0438\u0441\u043A\u0430</span><h3>\u0422\u043E\u0442 \u0436\u0435 \u0430\u0432\u0442\u043E\u0440</h3><p>\u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0430\u0432\u0442\u043E\u0440\u0430 \u0441 \u0443\u0436\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u043E\u0439 \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u043E\u0439. \u0412\u044B\u0431\u043E\u0440 \u0432 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0434\u0440\u0443\u0433\u0438\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C. <button data-scenario="author">\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0430\u0432\u0442\u043E\u0440\u0430 \u2192</button></p></article><article class="principle"><span class="pill-label">\u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439</span><h3>\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u0445\u043E\u0434, \u0437\u0430\u0442\u0435\u043C \u0442\u0435\u043A\u0441\u0442</h3><p>\u0413\u043E\u0441\u0442\u044C \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0438. \u041F\u043E\u0441\u043B\u0435 \u0432\u0445\u043E\u0434\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E\u043B\u0435; \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u0441\u0430\u043C \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C. <button data-scenario="comment">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u2192</button></p></article></div><p>\u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0442 \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0443 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044F: \u043F\u0440\u043E\u0441\u0442\u043E\u0439 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043E\u043A \u0441\u043E \u0441\u0447\u0451\u0442\u0447\u0438\u043A\u043E\u043C, \u043F\u0443\u0441\u0442\u043E\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043B\u0438\u0431\u043E \u0441\u0442\u0440\u043E\u043A\u0438 \u0441 \u0430\u0432\u0430\u0442\u0430\u0440\u043E\u043C, @handle \u0438 \u0432\u0440\u0435\u043C\u0435\u043D\u0435\u043C, \u0437\u0430\u043A\u0440\u0435\u043F\u043B\u0451\u043D\u043D\u043E\u0435 \u043F\u043E\u043B\u0435 \u0432\u043D\u0438\u0437\u0443. \u041B\u0438\u0448\u043D\u0438\u0435 \u043E\u0431\u044A\u044F\u0441\u043D\u0435\u043D\u0438\u044F \u0438 \u0432\u0432\u043E\u0434 \u0433\u043E\u0441\u0442\u0435\u0432\u043E\u0433\u043E \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A\u0430 \u0443\u0431\u0440\u0430\u043D\u044B.</p><p>\u041D\u0435\u0432\u0435\u0440\u043D\u044B\u0439 \u0438\u043B\u0438 \u0438\u0441\u0442\u0451\u043A\u0448\u0438\u0439 \u043A\u043E\u0434, \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u0430\u044F \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0430 \u0438 \u043E\u0448\u0438\u0431\u043A\u0430 \u0441\u0435\u0442\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0435 \u043D\u0430\u043C\u0435\u0440\u0435\u043D\u0438\u0435. \u041E\u0442\u0441\u0447\u0451\u0442 \u0434\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0439 \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0438 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0439 \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u0434\u0435\u043C\u043E\u043D\u0441\u0442\u0440\u0430\u0446\u0438\u0438. \u041F\u043E\u0441\u043B\u0435 \u0432\u0445\u043E\u0434\u0430 \u043D\u0430 \u0433\u0440\u0430\u043D\u0438\u0446\u0435 \u0433\u043E\u0441\u0442\u044F \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u044B\u0439 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0431\u043E\u043A. <button data-scenario="limit">\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0433\u0440\u0430\u043D\u0438\u0446\u0443 \u2192</button> <button data-scenario="expired">\u0418\u0441\u0442\u0451\u043A\u0448\u0438\u0439 \u043A\u043E\u0434 \u2192</button></p><p><strong>\u0414\u0440\u0443\u0433\u043E\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u0443\u044E \u0438\u0441\u0442\u043E\u0440\u0438\u044E \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.</strong> \u0420\u0430\u0431\u043E\u0447\u0438\u0439 \u043F\u0443\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442\u044C \u0432\u0432\u0435\u0441\u0442\u0438 \u043A\u043E\u0434 \u0442\u0430\u043C, \u0433\u0434\u0435 \u043D\u0430\u0447\u0430\u0442 \u0432\u0445\u043E\u0434. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0435 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0441\u043D\u043E\u0432\u0430. \u0412 \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F\u0435 \u043F\u0438\u0441\u044C\u043C\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F, \u0442\u0435\u0441\u0442\u043E\u0432\u044B\u0439 \u043A\u043E\u0434 \u2014 123456. \u041D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u0430\u0446\u0438\u044F, \u0441\u0432\u044F\u0437\u044C visitor id \u0438 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u044F \u0442\u0440\u0435\u0431\u0443\u044E\u0442 Supabase.</p>'},{label:"08 / \u041A\u0430\u043A \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F",title:"\u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0432\u043A\u0443\u0441 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0432\u0438\u0434\u0438\u043C\u044B\u043C.",html:"<p>\u041B\u0438\u0447\u043D\u043E\u0435 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u044F\u0432\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0430\u0432\u0442\u043E\u0440\u043E\u0432 \u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0445 \u0432\u043E\u0441\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u0439. \u042D\u0442\u0438 \u0430\u0432\u0442\u043E\u0440\u044B \u043F\u043E\u043A\u0430\u0437\u0430\u043D\u044B \u0431\u0435\u0437 \u0440\u0430\u043D\u0433\u043E\u0432: \u0438\u0445 \u0432\u044B\u0431\u043E\u0440 \u043D\u0435 \u0441\u043E\u0437\u0434\u0430\u0451\u0442 \u043D\u0438 \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u0445 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0439, \u043D\u0438 \u043B\u0430\u0439\u043A\u043E\u0432 boks. \u0412\u043E\u0441\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u043B\u043E\u0432\u0430\u043C\u0438 \u0447\u0438\u0442\u0430\u0442\u0435\u043B\u044F, \u0430 \u043D\u0435 \u0434\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u043F\u0440\u043E\u0447\u0442\u0435\u043D\u0438\u044F. \u0418\u0445 \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0438\u043B\u0438 \u0443\u0431\u0440\u0430\u0442\u044C.</p><p>\u041D\u0430 \u043F\u0435\u0440\u0432\u043E\u043C \u043F\u043B\u0430\u043D\u0435 \xAB\u0412\u044B\xBB \u2014 \u0430\u0432\u0442\u043E\u0440\u044B: \u043B\u0438\u0447\u043D\u044B\u0435 \u0442\u043E\u043F\u044B \u043F\u043E\u044D\u0442\u043E\u0432 \u0438 \u043F\u0440\u043E\u0437\u0430\u0438\u043A\u043E\u0432 \u0441 \u043A\u0440\u0443\u043F\u043D\u044B\u043C\u0438 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u043C\u0438 \u043F\u043E\u0440\u0442\u0440\u0435\u0442\u0430\u043C\u0438. \u041C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0432\u043D\u0438\u0442\u044C \u0434\u0432\u0430 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u044F: \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043A \u0447\u0442\u0435\u043D\u0438\u044E \u0438 \u044F\u0432\u043D\u044B\u0435 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438. \u041E\u043D\u0438 \u043D\u0435 \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0431\u0430\u043B\u043B \u043B\u044E\u0431\u0432\u0438. \u041E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0434\u0430\u0451\u0442 \u043E\u0431\u0449\u0435\u0435 \u043C\u0435\u0441\u0442\u043E.</p><p>\u041D\u0430\u0436\u0430\u0442\u0438\u0435 \u043D\u0430 \u0430\u0432\u0442\u043E\u0440\u0430 \u0440\u0430\u0441\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0430\u0448\u0443 \u0441\u0432\u044F\u0437\u044C \u0441 \u043D\u0438\u043C: \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437 \u0432\u0435\u0440\u043D\u0443\u043B\u0438\u0441\u044C, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0435\u0433\u043E boks \u043F\u043E\u043D\u0440\u0430\u0432\u0438\u043B\u043E\u0441\u044C, \u043A\u0430\u043A\u0438\u0435 \u0442\u0435\u043A\u0441\u0442\u044B \u0441\u0442\u043E\u044F\u0442 \u0437\u0430 \u044D\u0442\u0438\u043C\u0438 \u0447\u0438\u0441\u043B\u0430\u043C\u0438. \u041A\u043E\u0440\u043E\u0442\u043A\u043E\u0435 \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u0435 \u043E \u0441\u0442\u0438\u0445\u0430\u0445 \u0438 \u043F\u0440\u043E\u0437\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0442\u043E\u0447\u043D\u043E\u0435 \u0441\u043E\u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u0441\u0440\u0435\u0434\u0438 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0439 \u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0440\u0438\u043C\u0435\u0440\u044B. \u042D\u0442\u043E \u043F\u043E\u0432\u043E\u0434 \u0443\u0437\u043D\u0430\u0442\u044C \u0447\u0442\u043E-\u0442\u043E \u043E \u0441\u0432\u043E\u0451\u043C \u0447\u0442\u0435\u043D\u0438\u0438, \u0430 \u043D\u0435 \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u044F\u0440\u043B\u044B\u043A.</p><p>\u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u043F\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C \u043A\u0432\u0430\u043B\u0438\u0444\u0438\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C \u0441\u0435\u0430\u043D\u0441\u0430\u043C \u0437\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0433\u043E\u0434; \u043F\u0435\u0440\u0432\u043E\u0435 \u0447\u0442\u0435\u043D\u0438\u0435 \u043D\u0435 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435\u043C. \u0421\u0438\u043C\u043F\u0430\u0442\u0438\u0438 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u043F\u043E \u0442\u0435\u043A\u0443\u0449\u0438\u043C \u044F\u0432\u043D\u044B\u043C \u043B\u0430\u0439\u043A\u0430\u043C, \u0431\u0435\u0437 \u0432\u044B\u0434\u0443\u043C\u0430\u043D\u043D\u044B\u0445 \u0434\u0430\u0442. \u0412\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u043D\u0435 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u0432 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u044B\u0439 \u0432\u043A\u0443\u0441. \u041F\u0440\u0438 \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u0438\u0441\u0442\u043E\u0440\u0438\u0438 \u0432\u0438\u0434\u043D\u044B \u043F\u0435\u0440\u0432\u044B\u0435 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0435 \u0430\u0432\u0442\u043E\u0440\u044B, \u0431\u0435\u0437 \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u043F\u0443\u0441\u0442\u044B\u0445 \u043C\u0435\u0441\u0442.</p><p>\u041A\u043E\u043C\u043F\u0430\u043A\u0442\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043D\u0438\u0436\u0435 \u0430\u0432\u0442\u043E\u0440\u043E\u0432 \u0438 \u0446\u0435\u043B\u0438\u043A\u043E\u043C \u043F\u043E\u043C\u0435\u0449\u0430\u044E\u0442\u0441\u044F \u0432 \u044D\u043A\u0440\u0430\u043D. \u041A\u0430\u043B\u0435\u043D\u0434\u0430\u0440\u044C \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438\u0437 \u0438\u0441\u0442\u043E\u0440\u0438\u0438. \u041F\u0440\u043E\u0444\u0438\u043B\u044C \u043F\u0440\u0438\u0432\u0430\u0442\u043D\u044B\u0439; \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0430 \u0434\u043B\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u044F\u0432\u043D\u044B\u0435 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0438 \u0438 @handle. \u0417\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043F\u0440\u0438\u043C\u0435\u0440 \u0438\u0437\u043E\u043B\u0438\u0440\u043E\u0432\u0430\u043D \u043E\u0442 \u043E\u0431\u044B\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0444\u0438\u043B\u044F. \u0412\u0441\u0442\u0440\u0435\u0447\u0430 \u0432\u0434\u043E\u0445\u043D\u043E\u0432\u043B\u044F\u0435\u0442 \u0438\u0434\u0435\u044E \u043B\u0438\u0447\u043D\u043E\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u0430, \u0430 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u0439 \u0447\u0430\u0440\u0442 \u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043F\u043E\u043A\u0430\u0437\u0430 \u2014 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u044D\u0442\u043E\u0439 \u0440\u0430\u0431\u043E\u0442\u044B.</p>"},{label:"09 / \u0427\u0442\u043E \u0437\u0434\u0435\u0441\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442",title:"\u041F\u0440\u043E\u0442\u043E\u0442\u0438\u043F \u0445\u0440\u0430\u043D\u0438\u0442 \u043F\u0443\u0442\u044C. \u041F\u0440\u043E\u0434\u0443\u043A\u0442 \u0435\u0449\u0451 \u043F\u0440\u0435\u0434\u0441\u0442\u043E\u0438\u0442 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C.",html:"<p>\u042D\u0442\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 Sites-\u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F \u0441 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u043C\u0438 \u0442\u0435\u043A\u0441\u0442\u0430\u043C\u0438, \u043E\u0431\u043B\u043E\u0436\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0440\u0442\u0440\u0435\u0442\u0430\u043C\u0438. \u0412 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0438\u043C\u0438\u0442\u0430\u0446\u0438\u044F \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430, \u0438\u0441\u0442\u043E\u0440\u0438\u044F, \u043B\u0430\u0439\u043A\u0438, \u043F\u043E\u0434\u043F\u0438\u0441\u043A\u0438, \u044D\u0442\u0430\u043F\u044B \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0430, \u043F\u043E\u043B\u043A\u0430 \u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0432\u043E\u0441\u043F\u043E\u043C\u0438\u043D\u0430\u043D\u0438\u044F. \u0421\u0446\u0435\u043D\u0430\u0440\u0438\u0439 \xAB\u0417\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E\xBB \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435 \u0438\u043C\u044F \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430 v18, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0435\u0436\u043D\u0438\u0435 \u043E\u0442\u0432\u0435\u0442\u044B \u043F\u0435\u0440\u0435\u0436\u0438\u043B\u0438 \u043E\u0444\u043E\u0440\u043C\u043B\u0435\u043D\u0438\u0435 v35; \u043E\u0431\u044B\u0447\u043D\u043E\u0435 \u0447\u0442\u0435\u043D\u0438\u0435 \u0438 \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043F\u0440\u0438\u043C\u0435\u0440 \u043B\u0438\u0447\u043D\u043E\u0433\u043E \u0447\u0430\u0440\u0442\u0430 \u0438\u043C\u0435\u044E\u0442 \u0441\u0432\u043E\u0438 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u0430. \u041F\u0435\u0440\u0435\u0445\u043E\u0434 \u043C\u0435\u0436\u0434\u0443 \u043D\u0438\u043C\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0435 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u0438 \u043D\u0435 \u043F\u043E\u0434\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u043F\u0440\u0438\u043C\u0435\u0440 \u0432 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C.</p><p>\u041C\u043E\u0434\u0435\u043B\u044C \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u0430 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u0443\u0435\u0442 BoksOnboarding \u0438 \u043E\u0442\u0434\u0435\u043B\u0435\u043D\u0430 \u043E\u0442 DOM \u0438 \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u0430\u0446\u0438\u0438. \u041E\u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0438\u0437\u0432\u0435\u0441\u0442\u043D\u044B\u0435 ID, \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0438 \u043E\u0447\u0438\u0449\u0430\u0435\u0442 \u0431\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u044E, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u043C\u043E\u0441\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0441\u0442\u0440\u043E\u0433\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0441\u0442\u044C. \u0427\u0438\u0441\u0442\u044B\u0435 \u0442\u0435\u0441\u0442\u044B \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0442 \u0434\u0432\u0438\u0436\u043E\u043A \u0447\u0442\u0435\u043D\u0438\u044F, \u043C\u043E\u0434\u0435\u043B\u044C \u043F\u0440\u043E\u0444\u0438\u043B\u044F \u0438 \u043C\u0430\u0440\u0448\u0440\u0443\u0442 \u043F\u043E \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u043C \u044F\u0437\u044B\u043A\u0430\u043C; \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044F \u043E\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u0443\u044E \u043A\u043D\u043E\u043F\u043A\u0443, \u0432\u0438\u0434\u0438\u043C\u0443\u044E \u0432\u044B\u0441\u043E\u0442\u0443 Safari, \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438, \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u043E\u043A\u043D\u0430 \u0438 \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u043D\u0438\u0435 resize. \u0411\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u0430\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u043E\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0442\u0435\u0441\u0442\u044B, \u043D\u043E \u043D\u0435 \u0434\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0443 \u043D\u0430 \u0432\u0441\u0435\u0445 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430\u0445 \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043B\u044E\u0431\u044B\u0445 \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u043E\u0448\u0438\u0431\u043E\u043A.</p><p><strong>\u041F\u0438\u0441\u044C\u043C\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0438 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0439 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u043D\u0435 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F.</strong> \u041D\u0435\u0442 \u043C\u0435\u0436\u0431\u0440\u0430\u0443\u0437\u0435\u0440\u043D\u043E\u0439 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438, Supabase Auth, \u0438\u043C\u043F\u043E\u0440\u0442\u0430 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u043E\u0432 \u0434\u0440\u0443\u0433\u0438\u0445 \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C, \u0437\u0430\u043F\u0438\u0441\u0438 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u0430\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0438 \u0438\u043B\u0438 \u0434\u043E\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u043E\u0431\u0443\u0447\u0435\u043D\u0438\u044F. \u0418\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u0440\u0443\u0441\u0441\u043A\u0438\u0439 \u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439; \u0442\u0435\u043A\u0441\u0442\u044B \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u044F\u0437\u044B\u043A. \u0414\u043B\u044F \u0432\u043D\u0435\u0434\u0440\u0435\u043D\u0438\u044F \u043D\u0443\u0436\u043D\u044B \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u043E\u0432\u0430\u044F \u0441\u043F\u0435\u0446\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u044F, \u0441\u0435\u0440\u0432\u0435\u0440\u043D\u044B\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u044B \u0431\u0438\u043E\u0433\u0440\u0430\u0444\u0438\u0438 \u0438 \u043F\u043E\u0434\u043F\u0438\u0441\u043E\u043A, \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435, \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u044B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u044B \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0441\u0442\u0438. \u0415\u0434\u0438\u043D\u0443\u044E \u043B\u0435\u043D\u0442\u0443, \u0433\u0440\u0430\u043D\u0438\u0446\u044B 5/10/15, foreground measurement \u0438 \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 Worker \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C. \u0420\u0430\u0431\u043E\u0447\u0438\u0439 boks \u044D\u0442\u0438\u043C \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F\u043E\u043C \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0451\u043D.</p>"}]},en:{eyebrow:"Concept \xB7 revision 41",title:"Your own place begins with your writers.",lead:"A warm room, a tall cabinet and a crowded shelf to explore. Choose reading languages, form and familiar writers. A living picture introduces Series, mail brings lines from other readers, and a monthly Afisha introduces a future literary programme. Start reading at any time.",sections:[{label:"01 / Where this comes from",title:"The meeting defines how to treat a reader.",html:'<p>The 14 and 15 November discussions define how to treat readers: retain their actions and context, welcome them and help them establish a place of their own. The screens below are implementation proposals, not a route approved word for word in the meeting.</p><div class="scenario-table"><table><thead><tr><th>Source</th><th>What it says</th><th>Prototype consequence</th></tr></thead><tbody><tr><td>14 November, lines 626\u2013636, 764\u2013802, 874\u2013875</td><td>Recognition on return, retained likes, a path after arrival and hospitality.</td><td>Restore actual actions and reading place rather than substituting a greeting.</td></tr><tr><td>15 November, part 3, 12:04\u201316:01; lines 1413\u20131461</td><td>Challenge an arbitrary first-work landing; offer recognisable names, optional deeper reading biography and visible personal growth.</td><td>A warm room \u2192 familiar writers \u2192 the first actual reading. Deeper recollection is optional.</td></tr><tr><td>15 November, part 3, 16:01\u201319:09</td><td>Separate time spent from reasons to return; optional games and future rewards were discussed.</td><td>Light playful feedback for actual choices, with no currency or mandatory game.</td></tr><tr><td>15 November, part 3, 21:15\u201322:19</td><td>A separate current request: mood, poetry/prose and classic/contemporary authors.</td><td>Never turn a temporary request into a permanent personality label.</td></tr></tbody></table></div><p>The meeting described a minimum choice as mandatory; five out of twenty and a progress image were examples. The latest user request explicitly requires avoiding unwanted tasks. This implementation therefore allows any number of available writers, including zero, and keeps a direct reading exit. Sign-in timing and direct-link exceptions were not settled in the call. Their recovery contracts here are design choices.</p>'},{label:"Discovery / revision 41",title:"Meet Boks through small actions.",html:"<p>The November 16 discussion supported a library world with independent discoveries. The crowded shelf retains spines, covers and stacks. Horizontal books show a solid, straight-on cloth binding without an artificial top-cover plane. A tap brings the book from its shelf position towards the reader; a separate white Choose author / Remove button sits below it. Tapping the open cover, closing it, tapping outside or pressing Escape returns it without changing affinity. Focus stays inside inspection and returns to the source. Resize and stage changes clear this temporary view. There is no quota or invented follow.</p><p>Authentic Series previews retain their original recordings, illustrations and aligned words. Russian reading starts with Alexey Prokhorov\u2019s \xAB\u043F\u043E\u043B\u0435\u0442 \u0441\u043A\u0432\u043E\u0437\u044C \u0441\u043D\u044B\xBB, with Darya Mallo-Subbotina\u2019s \xAB\u0417\u0432\u0451\u0437\u0434\u043D\u043E\u0435\xBB also available. English reading starts with Emily Dickinson\u2019s \u201CThere is no Frigate like a Book\u201D, with Poe\u2019s \u201CA Dream Within a Dream\u201D also available. These are separate room previews, not additions to the reader catalogue. The picture and words play silently on their own, and works cycle automatically. There are no arrows or manual work controls; a tap only toggles sound. Velvet curtains begin closed and leave the frame completely. Start reading at any time.</p><p>In revision 35, Series typography keeps a logical width of 390 and derives its height from the actual picture opening. The former fixed 390\xD7693\u2153 stage is no longer uniformly shrunk to tiny words. Production Playfair styling, weights, textScale, phrase behaviour, aligned word arrivals and motion remain the reference. Each text zone fits independently around measured fixed credits. Title and byline stay together at the top; all words must remain inside. The lower progress line stays removed. A 2px opaque inner frame edge masks compositing seams.</p><p>The camera pans across one continuous room panorama towards the desk, then approaches its surface. No walls rotate and there is no cube transition. Optical scale follows sampled intermediate poses smoothly, without the former midpoint zoom pulse. Tall phones retain full panoramic coverage without moving the painting\u2019s upper anchor. Paper appears only after the approach. Between mail and Afisha, the view moves across the same desk: the outgoing object leaves before the next arrives.</p><p>Mail offers one sheet to try. Touching genuine lines exposes Send a line. The selected original sheet folds with top and bottom hinges, enters an open envelope, the flap closes and the sealed letter travels into the visible slot. The wax seal appears only during closing. No second page remains beneath it: sending leaves the bare desk and a quiet status. The envelope to the right is decoration with no caption or action. The destination fits the mailbox\u2019s brass plaque. Unchanged-size ResizeObserver notifications preserve motion; real resizing, departure or reduced motion safely settle or cancel the owned sequence. Returning offers a fresh local sample. Copy connects selected bok lines with a random reader and received letters with the profile. This local illustration sends nothing, creates no recipient and promises no instant response.</p><p>The monthly Afisha uses the first of five proposals, selected for revision 40: forest-green and carmine print with photographs, theatre-style tickets and a small poster resting on the calendar grid. The larger transparent cutout keeps the paper and its soft shadow directly on the room\u2019s desk. Its aspect ratio is preserved inside the measured space between the heading and bottom button. The artwork contains no text: one shared native SVG layer supplies Russian or English print in both onboarding and the separate five-variant review. Dates follow the measured boundaries of all 42 cells, including unequal row heights; ticket and poster baselines follow their physical paper planes. Masks keep print behind overlapping objects. The week starts on Monday, and native date formatting localises the month, year, weekdays and dates. There are no clickable events or bookings. This introduces a future literary programme rather than an actual schedule or author availability. No attendance, registration or reading history is written. Personal reading history remains a separate profile view.</p><p>Back retains answers and place. Camera travel reverses from the current frame. Leaving stops media and clears interaction guards. Interface language remains separate from the language of literary examples. Source and viewport checks supplement browser review; verifying one composition does not establish behaviour on every device.</p>"},{label:"02 / The first encounter",title:"An introduction inside one living cabinet.",html:'<p>The opening keeps the arched window, olive chair, side table and warm light. \u201CWelcome to Boks\u201D and \u201CFind stories and poems that feel like you.\u201D explain the encounter. A subtle \u201COpen the cabinet\u201D caption sits near the lower part of the front. A tall, wide walnut cabinet continues beyond the right edge; its broad frosted front moves along a rail, with a fixed mask keeping the table in front. The route visits languages \u2192 form \u2192 classics \u2192 contemporary writers when Russian is selected. With English only, preferences end after classics; the three optional discovery scenes follow, and progress reports three preference sections instead of four. <button data-scenario="onboarding">Try the introduction \u2192</button></p><p>Two independent brass switches select Russian and English: either or both. A fresh profile starts with Russian only, independently of interface language; stored explicit choices remain unchanged. The final language cannot be switched off. Illumination, a check and a bright caption show selection; an unselected caption dims. Reading languages strictly constrain actual boks and remain separate from interface language.</p><p>Three fitted drawers represent Prose, Poetry and Either, as one answer. Warm light inside the selected brass handle recess and a matte check indicate the answer. The wooden face stays stationary at its original size, colour and texture, without flooding the front or joinery with light. Every front keeps the exact original crop and its registered live label; there is no dissolve between independently generated states. A closed base stays visible until layers are ready; only plain paper edges appear inside. This is a soft starting affinity, not a prohibition on another form or the later temporary What to read filter.</p><p>Classics match the chosen reading languages. Books rest on shelves, names remain accessible HTML, and portrait references appear as photogravure or debossing. Originals are preserved; a reproduction is not represented as unchanged photograph pixels. Volumes contain no text or excerpts. The contemporary section offers twelve Russian-language affinities only when Russian is selected. Alexey Prokhorov, Dmitry Vodennikov and Darya Mallo-Subbotina are already on the platform according to the user; the other nine are an editorial expansion of poets and short-prose writers, not an objective ranking. The proposal is limited to those forms, with bibliographic sources recorded separately. Former novel-focused examples are excluded from onboarding choices while their historical profile records remain. Cloth editions use genuine black-and-white photographs, including the corrected Darya image supplied by the user. With English only, both objects and the step are omitted; previous affinities are retained.</p><p>Back returns one eligible step. Skip on a writer section passes only that section and retains choices. Skip setup on the welcome opens reading. Either is a complete answer, with no writer quota. One ordinary paper-white button, 56 CSS pixels high, stays at the bottom of the screen independently of the camera. Screwed-in plaques and round navigation caps between books are removed. Back and current-step Skip remain in the header; writer shelves retain separate positions. Footer and header respond immediately after a drag: suppression of a trailing book tap does not swallow navigation. A slow gesture or interrupted inertia does not leave the books blocked. Headings keep measured clearance from navigation, viewport edges and furniture independently of camera scale. Keyboard focus uses soft local illumination instead of a detached rectangular frame.</p><p>The world persists between answers. Sampled optical poses make lateral travel smooth without the former midpoint zoom pulse; interruptions and resize continue from the current rendered matrix. The front opens by tap or a qualifying horizontal drag. Continuation is blocked during route travel but stays usable during ordinary panning. Framing respects Safari visible height and device safe area, keeping mechanisms above the fixed button. Hints retain at least 12 screen pixels. Short windows allow scene movement by gesture, keyboard or focus. Author framing follows width in portrait and also caps zoom by available first-row height in a low landscape window, retaining a readable minimum instead of landing below the books. A continuous wall texture and the room artwork\u2019s soft right edge cover the former rail seam.</p><p>Yellow ribbon animations are paused in the introduction and reading-request changes while their motion is developed separately. No mascot flight or delayed selection stamp runs. Camera and cabinet-front movement remain; form selection changes only its local light and check. Answers save before effects; reduced motion places the scene at its destination. rAF diagnostics describe main-thread intervals, not every GPU-presented frame or guaranteed performance on all phones.</p><p>New plaque-free bays, fixed recesses, registered fronts, built-in imagegen prompts, provenance and geometry are in assets/onboarding/integrated-v30. Room and front retain opening-prefixed records in integrated-v28; author modules remain in wide-v26, classic bindings in books-v25 and contemporary materials in modern-v29. The corrected Darya photograph, original and provenance are in assets/authors/contemporary-v29; other retained photos remain in contemporary-v27, with new portraits and bibliographic provenance in contemporary-v31. This prototype still has fourteen actual boks; no contemporary work or translation was added to the reader catalogue. Authentic contemporary Series assets appear only in the separate room preview. There is no XP, currency, percentage of understood taste or automatic following.</p>'},{label:"03 / From an answer to a suggestion",title:"Affinity, following and reading are separate evidence.",html:'<div class="scenario-table"><table><thead><tr><th>Action</th><th>Use</th><th>No inferred consequence</th></tr></thead><tbody><tr><td>Chooses a close writer</td><td>Stores an explicit starting affinity and a soft initial boost to eligible boks.</td><td>No follow, bok like, read or personal chart position is created.</td></tr><tr><td>Follows a writer</td><td>A separate account-gated relationship with a canonical byline.</td><td>The introduction never applies it automatically.</td></tr><tr><td>Recalls a writer or book</td><td>Stores the reader\u2019s words in their biography.</td><td>A free note creates no catalogue bok, measured read or fictitious model understanding.</td></tr><tr><td>Chooses a mood</td><td>A temporary soft request; form, groups and languages determine hard eligibility.</td><td>It is no permanent taste. Zero results never silently widen eligibility.</td></tr><tr><td>Reads and marks boks</td><td>Likes, foreground time, progress and separate sessions provide their own facts.</td><td>An opening or missing heart alone proves no preference.</td></tr></tbody></table></div><p>The actual sample has fourteen boks by twelve classic bylines; twelve contemporary names are affinity-only additions, and initial choices are no longer truncated to three. The starting form is also soft and never changes hard eligibility. The demonstrated seed weight of 2.5 fades as measured reading accumulates; it does not validate recommendation quality. Feed diversity and hard language/editorial conditions remain. Existing accounts retain their canonical starting state by default. An explicit edit begun while signed in can update it, with that intention recovered over reload.</p><p>Classics may be published by one import account, but their byline relationship must not accidentally follow that account. Production needs authorised server contracts and bounded candidate queries. Served slates and versioned ranking inputs belong in the canonical Worker.</p>'},{label:"04 / For this break",title:"Feel a little sad. Have fun. Reflect.",html:'<div class="concept-grid"><article class="principle"><span class="pill-label">Feel a little sad</span><h3>Spend time with a feeling</h3><p>Quiet sadness, memory, tenderness or loss. Wanting a sad work says nothing definite about the reader\u2019s emotional state.</p></article><article class="principle"><span class="pill-label">Have fun</span><h3>Find a precise little delight</h3><p>Humour, irony, play and an unexpected turn. Lightness need not mean a shallow work.</p></article><article class="principle"><span class="pill-label">Reflect</span><h3>Take a question away</h3><p>An unfamiliar perspective, a difficult choice or a thought that remains after the last line.</p></article></div><p>What to read on the main cover opens a panel inside the boks screen, including the framed phone on desktop: mood, prose or poetry, and Classics or Contemporary authors. The reading rail has no such control. The circular illustration has a blurred background and no vertical divider. Edits remain a draft until Apply; applying immediately opens a new eligible bok. Ribbon transition is paused, so the new work opens immediately; the guest boundary still applies. Closing cancels the draft. Zero matches never silently widen the conditions; an exact condition can be removed.</p><p>Mood is soft; form and chosen author groups are hard conditions. Multiple author groups use OR. This sample has no Contemporary texts and never presents classics as a contemporary result. Temporary conditions reset after thirty minutes without reading.</p><p>Mood uses editorial matches as a soft preference. Without an exact match, ranking continues within the chosen form, author groups and reading languages. Hard conditions never widen themselves. Aftertaste remains a separate observation about the work just read.</p>'},{label:"05 / Arrivals and returns",title:"Fulfil the promise of the entrance first.",html:'<div class="scenario-table"><table><thead><tr><th>Entry</th><th>Behaviour</th></tr></thead><tbody><tr><td>First ordinary visit</td><td>Room \u2192 languages \u2192 form \u2192 classics \u2192 contemporary writers \u2192 optional Series, mail and events discovery \u2192 the actual first reading. Writer sections can be skipped; the welcome offers a direct reading exit. <button data-scenario="home">Try \u2192</button></td></tr><tr><td>Direct bok link</td><td>The promised work opens without onboarding above it. <button data-scenario="direct">Try \u2192</button></td></tr><tr><td>Author entry</td><td>The author and available boks. Reader setup never replaces this entry. <button data-scenario="author">Try \u2192</button></td></tr><tr><td>Unfinished introduction</td><td>Choices, stage and camera position are retained; optional recollections remain available later in the profile. <button data-scenario="onboarding">Try \u2192</button></td></tr><tr><td>Returning reader</td><td>A completed or skipped introduction does not automatically repeat. A held bok keeps its reading position. <button data-scenario="returning">Try \u2192</button></td></tr><tr><td>Account and recovery</td><td>Own actions and the original intention survive. A new account inherits its answers; an existing account does not lose its prior seed to guest setup. <button data-scenario="account">Try \u2192</button></td></tr></tbody></table></div><p>The ordinary cover has no welcome line or resume strip. The warm welcome belongs to the useful first introduction. Initial affinities never become forced follows. Literary byline and account @handle remain different identities. A publishing author\u2019s cabinet is a separate route.</p>'},{label:"06 / An invitation to an account",title:"A reason to keep something comes first.",html:'<p>The first bok can be read without signing in. After reactions, guests see a universal invitation to boks: more of what moves them, favourite authors, new discoveries and a feed that fits their taste. It has no work-specific question, cover or discussion action. Sign in to boks opens email sign-in and returns to reading. Signed-in readers do not see this invitation. Choosing close writers, the personal shelf and recalled biography need no account. The welcome offers a direct reading exit; both writer sections offer a current-step skip. Guests can read boks and comments and choose temporary conditions without email. The guest comments sheet has no composer. A like, comment or follow asks for an account at the moment of that action. The benefit is concrete: favourites and the reader\u2019s own actions remain theirs.</p><div class="scenario-table"><table><thead><tr><th>Boundary</th><th>What happens</th><th>What remains available</th></tr></thead><tbody><tr><td>After five distinct boks</td><td>A small invitation between boks explains that ten remain without an account.</td><td>Keep reading with one action. <button data-scenario="fifth">After five \u2192</button></td></tr><tr><td>After ten</td><td>A calm reminder: five remain, then email sign-in is needed.</td><td>Continue without signing in immediately. <button data-scenario="tenth">After ten \u2192</button></td></tr><tr><td>After fifteen</td><td>Sign-in is required before opening the sixteenth new bok.</td><td>The current work can still be read and revisited. <button data-scenario="limit">The boundary at fifteen \u2192</button></td></tr></tbody></table></div><p>The allowance counts <strong>distinct boks with sufficient foreground reading time</strong> under the existing rule. It is no count of swipes, cover openings or measured reads. A repeated bok uses no extra allowance. Reloading does not reset a reached boundary.</p><p>Priority is the required boundary \u2192 sign-in for an action \u2192 the ten/five notice \u2192 optional introduction \u2192 feedback. Dismissing one surface never reveals a queue of more invitations. We promise no saved guest likes when guests could not like yet; we describe actual history and future favourites.</p>'},{label:"07 / Sign-in and recovery",title:"Return to the place the reader came from.",html:`<p>New and existing accounts share one email path, with a short Sign in heading and the action's reason. There is no \u201CI already have an account\u201D switch. No password is requested: production boks uses a magic link and six-digit code. Comments use @handle and request no full name.</p><div class="concept-grid"><article class="principle"><span class="pill-label">A like</span><h3>The same heart</h3><p>Successful sign-in applies the chosen action once. The bok and reading place remain. <button data-scenario="like">Try it \u2192</button></p></article><article class="principle"><span class="pill-label">A follow</span><h3>The same author</h3><p>The selected author page returns with the chosen follow already applied. Introduction choices remain a different action. <button data-scenario="author">Open an author \u2192</button></p></article><article class="principle"><span class="pill-label">A comment</span><h3>Sign in, then write</h3><p>Guests read comments. Sign-in reveals the composer; the reader sends the comment themselves. <button data-scenario="comment">Try it \u2192</button></p></article></div><p>Comments follow the reader's structure: a plain heading with count, an empty state or rows with avatar, @handle and time, and a fixed bottom composer. Extra explanations and guest draft entry are removed.</p><p>A wrong or expired code, resend and network failure preserve the original intention. The demonstration uses an actual resend countdown. Signing in at the guest boundary opens the promised next bok. <button data-scenario="limit">Try the boundary \u2192</button> <button data-scenario="expired">Expired code \u2192</button></p><p><strong>Another browser does not automatically receive local history.</strong> The production path may suggest entering the code where sign-in began. A consumed link does not become valid again. This prototype sends no email and uses demo code 123456. Actual authorisation, visitor-id linking and synchronisation require Supabase.</p>`},{label:"08 / Continuing the introduction",title:"Make your own taste visible.",html:"<p>The private space begins with explicitly chosen writers and the reader\u2019s own recollections. These writers are unranked: choosing them creates neither measured returns nor bok likes. Recollections remain the reader\u2019s words, not proof of a read, and can be added or removed.</p><p>You puts authors first: personal poet and prose-writer charts with prominent real portraits. Returns to reading and explicit likes are two separate bases that can be compared. They never become a composite affection score. Equal evidence earns a shared rank.</p><p>Opening an author reveals your own connection: return counts, explicit likes and the actual boks behind them. A compact poetry/prose observation states exact counts among likes and opens its evidence. This makes reading preferences visible without inventing a personality label.</p><p>Returns use separate qualified sessions over the past year; a first reading is not a return. Likes use current explicit hearts, without invented dates. Temporary mood does not become permanent taste. Sparse history shows real first authors without filling missing places.</p><p>Compact covers sit below authors and fit entirely inside the screen. Calendar and recent activity move into Reading history. The profile is private; a separate saved card contains explicit likes and the @handle only. The populated example is isolated from ordinary profiles. The meeting inspires a personal space; this chart and presentation rules are proposals made here.</p>"},{label:"09 / What works here",title:"The prototype remembers a path. Production comes later.",html:"<p>This is a separate static Sites prototype with actual writing, covers and portraits. Browser storage retains a simulated account, history, likes, follows, introduction stage, shelf and personal recollections. The Onboarding review scenario keeps its isolated v18 storage name so earlier answers survive the v35 world; ordinary reading and the populated personal-chart example have their own scopes. Changing scopes opens the corresponding storage and never adds sample history to the ordinary profile.</p><p>The introduction model exports BoksOnboarding separately from DOM and auth. It validates known IDs, bounds and sanitises biography, preserves repeatable results and checks hard eligibility. The pure suite covers the reading engine, profile model and language-dependent route; a separate regression suite checks the fixed footer, Safari visible height, safe area, short windows and resize retargeting. Browser checks supplement those tests; they prove neither every physical phone nor the absence of every future defect.</p><p><strong>No email is sent and no real account is created.</strong> There is no cross-browser synchronisation, Supabase Auth, import from other platform accounts, production analytics or validated learning. The interface supports Russian and English; works retain their own language. Production needs a product specification, authorised biography and follow contracts, actual auth/recovery, bounded queries and accessibility validation. Preserve the single feed, five/ten/fifteen guest boundaries, foreground measurement and canonical Worker. This prototype has not changed live boks.</p>"}]}});window.renderConcept=function(lang){const messages=conceptMessages[lang]||conceptMessages.en;return`<div class="concept-lead"><span class="eyebrow">${messages.eyebrow}</span><h1>${messages.title}</h1><p>${messages.lead}</p></div>${messages.sections.map(section=>`<section class="concept-section"><span class="eyebrow">${section.label}</span><h2>${section.title}</h2>${section.html}</section>`).join("")}`};
;
(()=>{"use strict";function capture(){return null}function cancel(){}function play(_host,{done}={}){typeof done=="function"&&done()}window.BoksIntentMotion=Object.freeze({play,capture,cancel})})();
;
(()=>{"use strict";const copy=defineMessages({ru:{choose:"\u0427\u0442\u043E \u043F\u043E\u0447\u0438\u0442\u0430\u0442\u044C",compact:"\u041F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u044F",triggerSub:"\u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435, \u0444\u043E\u0440\u043C\u0430, \u0430\u0432\u0442\u043E\u0440\u044B",mood:"\u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435",sad:"\u041F\u043E\u0433\u0440\u0443\u0441\u0442\u0438\u0442\u044C",fun:"\u041F\u043E\u0432\u0435\u0441\u0435\u043B\u0438\u0442\u044C\u0441\u044F",think:"\u041F\u043E\u0434\u0443\u043C\u0430\u0442\u044C",form:"\u0424\u043E\u0440\u043C\u0430",any:"\u041B\u044E\u0431\u0430\u044F",prose:"\u041F\u0440\u043E\u0437\u0430",poetry:"\u041F\u043E\u044D\u0437\u0438\u044F",authors:"\u0410\u0432\u0442\u043E\u0440\u044B",classics:"\u041A\u043B\u0430\u0441\u0441\u0438\u043A\u0438",contemporary:"\u0421\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435",one:"\u041F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 1 bok",many:"\u041F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 {count} boks",softCount:"{count} boks \xB7 \u0431\u0435\u0437 \u0442\u043E\u0447\u043D\u043E\u0433\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F",zero:"\u0412 \u044D\u0442\u043E\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442 boks",soft:"\u0422\u043E\u0447\u043D\u043E\u0433\u043E \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u044F \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442.",anyAuthors:"\u041B\u044E\u0431\u044B\u0435 \u0430\u0432\u0442\u043E\u0440\u044B",anyForm:"\u041B\u044E\u0431\u0430\u044F \u0444\u043E\u0440\u043C\u0430",reset:"\u0421\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u0451",apply:"\u041F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C",applied:"\u041B\u0435\u043D\u0442\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0430",close:"\u0417\u0430\u043A\u0440\u044B\u0442\u044C"},en:{choose:"What to read",compact:"Reading wishes",triggerSub:"Mood, form and authors",mood:"Mood",sad:"Feel wistful",fun:"Have fun",think:"Reflect",form:"Form",any:"Either",prose:"Prose",poetry:"Poetry",authors:"Authors",classics:"Classics",contemporary:"Contemporary",one:"1 matching bok",many:"{count} matching boks",softCount:"{count} boks \xB7 no exact mood match",zero:"No boks match this combination yet",soft:"No exact mood match yet.",anyAuthors:"Any authors",anyForm:"Either form",reset:"Clear all",apply:"Apply",applied:"Feed updated",close:"Close"}}),t=(lang,key,vars={})=>Object.entries(vars).reduce((s,[k,v])=>s.replaceAll("{"+k+"}",String(v)),copy[lang][key]),esc=value=>String(value!=null?value:"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]),icon=key=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+window.BoksIcons[key]+"</svg>",groups=["classics","contemporary"];function from(profile){var _a,_b;return{mood:profile.intent||null,format:((_a=profile.readingRequest)==null?void 0:_a.format)||"any",authorGroups:[...((_b=profile.readingRequest)==null?void 0:_b.authorGroups)||[]]}}function summary(profile,lang){const request=from(profile),parts=[];return request.format!=="any"&&parts.push(t(lang,request.format)),request.authorGroups.forEach(g=>parts.push(t(lang,g))),request.mood&&parts.push(t(lang,request.mood)),{count:+!!request.mood+ +(request.format!=="any")+ +(request.authorGroups.length>0),full:parts.join(" \xB7 "),short:parts.length?parts.slice(0,2).join(" \xB7 ")+(parts.length>2?" \xB7 +"+(parts.length-2):""):t(lang,"triggerSub")}}function render({lang,draft,profile,library,currentId,animate=!1}){const J=window.BoksJourney,request={format:draft.format,authorGroups:draft.authorGroups},candidates=J.eligible({...profile,readingRequest:request},library,currentId),availabilityText=candidates.length?"":t(lang,"zero");return'<button class="reading-request-backdrop" data-action="dismiss" aria-label="'+t(lang,"close")+'" tabindex="-1"></button><section id="reading-request" class="reading-request-panel '+(animate?"is-entering":"")+'" role="dialog" aria-modal="true" aria-labelledby="reading-request-title"><header class="reading-request-header"><div><h2 id="reading-request-title" tabindex="-1">'+t(lang,"choose")+'</h2></div><button class="request-close" data-action="dismiss" aria-label="'+t(lang,"close")+'">'+icon("close")+'</button></header><div class="reading-request-body"><section class="request-section"><h3>'+t(lang,"mood")+'</h3><div class="request-moods">'+["sad","fun","think"].map(kind=>'<button class="request-mood" aria-pressed="'+(draft.mood===kind)+'" data-request-mood="'+kind+'" data-request-key="mood-'+kind+'"><span class="request-mood-art"><img src="assets/mood-icons-v2/'+kind+'.webp" alt=""><span>'+icon("check")+"</span></span><strong>"+t(lang,kind)+"</strong></button>").join("")+'</div></section><section class="request-section"><h3>'+t(lang,"form")+'</h3><div class="request-form" role="group" aria-label="'+t(lang,"form")+'">'+["any","prose","poetry"].map(value=>'<button data-request-form="'+value+'" data-request-key="form-'+value+'" aria-pressed="'+(draft.format===value)+'">'+t(lang,value)+"</button>").join("")+'</div></section><section class="request-section"><h3>'+t(lang,"authors")+'</h3><div class="request-authors">'+groups.map(g=>'<button data-request-author="'+g+'" data-request-key="author-'+g+'" aria-pressed="'+draft.authorGroups.includes(g)+'"><span class="request-author-top"><strong>'+t(lang,g)+'</strong><span class="request-author-check">'+icon("check")+"</span></span></button>").join("")+'</div></section></div><footer class="reading-request-footer"><div class="request-footer-meta"><span class="'+(candidates.length?"":"no-matches")+'" role="status">'+availabilityText+'</span><button data-request-reset data-request-key="reset">'+t(lang,"reset")+'</button></div><button class="request-apply" data-request-apply data-request-key="apply" '+(candidates.length?"":"disabled")+">"+t(lang,"apply")+icon("arrow")+"</button></footer></section>"}window.BoksReadingRequest={t,from,summary,render}})();
;
